-- ============================================================
-- FILE: dashboard/supabase/migrations/0001_init.sql
-- ============================================================

-- The Observance — dashboard schema
-- 0001_init.sql
--
-- The Minecraft plugin (service role) WRITES game state into these tables.
-- The dashboard READS that state and WRITES a few control rows
--   (approve/skip beats, edit whisper budgets, toggle watcher-sleep, advance the arc act).
--
-- Security model:
--   * RLS is enabled on EVERY table.
--   * The plugin connects with the service_role key, which BYPASSES RLS — it can do anything.
--   * Dashboard admins connect as `authenticated` users; policies below grant them full read/write.
--     (App-level admin gating is enforced by ADMIN_EMAILS in the Next.js layer.)
--   * `anon` (public / spoiler-free status mode) gets NO table access at all — only the three
--     spoiler-free VIEWS at the bottom of this file are GRANTed to anon.
--
-- Everything runs in the `public` schema.

begin;

-- ---------------------------------------------------------------------------
-- Tables
-- ---------------------------------------------------------------------------

create table if not exists public.players (
  id          uuid primary key default gen_random_uuid(),
  mc_uuid     text unique not null,
  name        text not null,
  first_seen  timestamptz default now(),
  last_seen   timestamptz default now()
);

create table if not exists public.dossiers (
  player_id      uuid primary key references public.players(id) on delete cascade,
  solo_ratio     numeric default 0,
  deaths         int default 0,
  hoard_summary  text,
  group_distance numeric,
  chat_sentiment numeric,
  blocks_mined   int default 0,
  updated_at     timestamptz default now()
);

create table if not exists public.custom_compliance (
  id              bigserial primary key,
  player_id       uuid references public.players(id) on delete cascade,
  custom_key      text not null,
  last_observed   timestamptz,
  violation_count int default 0,
  status          text default 'unknown',
  unique (player_id, custom_key)
);

create table if not exists public.heatmap_cells (
  id         bigserial primary key,
  world      text not null,
  cell_x     int not null,
  cell_z     int not null,
  visits     int default 0,
  updated_at timestamptz default now(),
  unique (world, cell_x, cell_z)
);

create table if not exists public.bases (
  id              bigserial primary key,
  owner_player_id uuid references public.players(id) on delete set null,
  world           text,
  x               int,
  z               int,
  confidence      numeric default 0,
  updated_at      timestamptz default now()
);

create table if not exists public.whisper_budgets (
  id        bigserial primary key,
  player_id uuid references public.players(id) on delete cascade,
  act       int not null,
  budget    int default 3,
  spent     int default 0,
  earned    int default 0,
  unique (player_id, act)
);

create table if not exists public.whisper_events (
  id         bigserial primary key,
  player_id  uuid references public.players(id) on delete cascade,
  puzzle_key text,
  tier       int,
  created_at timestamptz default now()
);

create table if not exists public.bond_ledger (
  player_id   uuid primary key references public.players(id) on delete cascade,
  bond_points int default 0,
  updated_at  timestamptz default now()
);

create table if not exists public.arc_state (
  id          int primary key default 1 check (id = 1),
  current_act int default 1,
  gates       jsonb default '{}'::jsonb,
  flags       jsonb default '{}'::jsonb,
  updated_at  timestamptz default now()
);

create table if not exists public.beat_queue (
  id         bigserial primary key,
  type       text not null,
  target     text,
  payload    jsonb default '{}'::jsonb,
  status     text default 'pending' check (status in ('pending','approved','skipped','fired')),
  created_at timestamptz default now(),
  decided_at timestamptz
);

create table if not exists public.event_log (
  id         bigserial primary key,
  level      text default 'info' check (level in ('info','warn','error')),
  source     text,
  message    text,
  created_at timestamptz default now()
);

create table if not exists public.settings (
  key        text primary key,
  value      jsonb not null,
  updated_at timestamptz default now()
);

-- ---------------------------------------------------------------------------
-- Indexes
-- ---------------------------------------------------------------------------

-- heatmap lookups + the unique constraint already covers (world,cell_x,cell_z);
-- keep an explicit composite index for clarity / forward-compat.
create index if not exists idx_heatmap_cells_world_xz
  on public.heatmap_cells (world, cell_x, cell_z);

-- beat queue is filtered by status (pending/approved/...) constantly.
create index if not exists idx_beat_queue_status
  on public.beat_queue (status);

-- health view scans recent events by time.
create index if not exists idx_event_log_created_at
  on public.event_log (created_at desc);

-- common foreign-key / time access paths.
create index if not exists idx_custom_compliance_player
  on public.custom_compliance (player_id);
create index if not exists idx_bases_owner_player
  on public.bases (owner_player_id);
create index if not exists idx_whisper_budgets_player_act
  on public.whisper_budgets (player_id, act);
create index if not exists idx_whisper_events_player
  on public.whisper_events (player_id, created_at desc);

-- ---------------------------------------------------------------------------
-- updated_at maintenance
-- ---------------------------------------------------------------------------

create or replace function public.set_updated_at()
returns trigger
language plpgsql
as $$
begin
  new.updated_at = now();
  return new;
end;
$$;

do $$
declare
  t text;
begin
  foreach t in array array[
    'dossiers', 'heatmap_cells', 'bases', 'bond_ledger', 'arc_state', 'settings'
  ]
  loop
    execute format('drop trigger if exists set_updated_at on public.%I;', t);
    execute format(
      'create trigger set_updated_at before update on public.%I
         for each row execute function public.set_updated_at();', t);
  end loop;
end;
$$;

-- ---------------------------------------------------------------------------
-- Row Level Security — enabled on EVERY table.
-- ---------------------------------------------------------------------------
-- service_role bypasses RLS (the plugin). authenticated (dashboard admins) get
-- full read/write via the policies below. anon gets nothing at the table level.

alter table public.players           enable row level security;
alter table public.dossiers          enable row level security;
alter table public.custom_compliance enable row level security;
alter table public.heatmap_cells     enable row level security;
alter table public.bases             enable row level security;
alter table public.whisper_budgets   enable row level security;
alter table public.whisper_events    enable row level security;
alter table public.bond_ledger       enable row level security;
alter table public.arc_state         enable row level security;
alter table public.beat_queue        enable row level security;
alter table public.event_log         enable row level security;
alter table public.settings          enable row level security;

-- One full-access policy per table for the `authenticated` role.
-- (App-level ADMIN_EMAILS allowlist further restricts who reaches these queries.)
do $$
declare
  t text;
begin
  foreach t in array array[
    'players', 'dossiers', 'custom_compliance', 'heatmap_cells', 'bases',
    'whisper_budgets', 'whisper_events', 'bond_ledger', 'arc_state',
    'beat_queue', 'event_log', 'settings'
  ]
  loop
    execute format('drop policy if exists "authenticated_all" on public.%I;', t);
    execute format(
      'create policy "authenticated_all" on public.%I
         for all to authenticated
         using (true) with check (true);', t);
  end loop;
end;
$$;

-- Lock down default grants: anon and authenticated should not get blanket table
-- privileges from Supabase defaults. authenticated is re-granted explicitly below.
revoke all on all tables in schema public from anon;
revoke all on all tables in schema public from authenticated;

grant select, insert, update, delete on all tables in schema public to authenticated;
grant usage, select on all sequences in schema public to authenticated;

-- ---------------------------------------------------------------------------
-- Spoiler-free VIEWS — the ONLY things anon may read.
-- No story labels, no player identity, no custom_key labels.
-- ---------------------------------------------------------------------------
--
-- These are SECURITY DEFINER views (security_invoker = false, the Postgres
-- default). They run with the privileges of the view OWNER (the migration role,
-- which owns the underlying tables), so anon can read the neutral projection
-- WITHOUT any table-level grant and WITHOUT any anon RLS policy on the base
-- tables. anon never touches the raw rows — only the columns these views expose.

-- v_health: last fired-beat time, 24h info/warn/error counts, and the
-- watcher_sleep + api/whisper status pulled from settings. Single row.
create or replace view public.v_health
with (security_invoker = false) as
select
  (select max(decided_at) from public.beat_queue where status = 'fired')           as last_beat_at,
  (select count(*) from public.event_log
     where level = 'info'  and created_at > now() - interval '24 hours')           as info_24h,
  (select count(*) from public.event_log
     where level = 'warn'  and created_at > now() - interval '24 hours')           as warn_24h,
  (select count(*) from public.event_log
     where level = 'error' and created_at > now() - interval '24 hours')           as error_24h,
  coalesce((select value from public.settings where key = 'watcher_sleep'), 'false'::jsonb)   as watcher_sleep,
  coalesce((select value from public.settings where key = 'api_status'),    '"unknown"'::jsonb) as api_status,
  coalesce((select value from public.settings where key = 'whisper_status'), '"unknown"'::jsonb) as whisper_status;

-- v_heatmap: spatial visit density, no player identity.
create or replace view public.v_heatmap
with (security_invoker = false) as
select
  world,
  cell_x,
  cell_z,
  visits
from public.heatmap_cells;

-- v_compliance_counts: NEUTRAL aggregate only. Total records + total flags
-- across ALL players. No player names, no custom_key labels.
create or replace view public.v_compliance_counts
with (security_invoker = false) as
select
  count(*)::bigint                            as total_records,
  coalesce(sum(violation_count), 0)::bigint   as total_flags
from public.custom_compliance;

-- Grant SELECT on just the three spoiler-free views to anon (and authenticated).
-- Because the views are SECURITY DEFINER, this is the ONLY public read surface:
-- anon has no table grants and no base-table RLS policies, so it physically
-- cannot reach raw dossiers, names, custom_key labels, or story state.
grant select on public.v_health            to anon, authenticated;
grant select on public.v_heatmap           to anon, authenticated;
grant select on public.v_compliance_counts to anon, authenticated;

commit;


-- ============================================================
-- FILE: dashboard/supabase/migrations/0002_seed.sql
-- ============================================================

-- The Observance — dashboard schema
-- 0002_seed.sql
--
-- Idempotent seed of control/status rows the dashboard and plugin both depend on.
-- Safe to re-run: every insert is ON CONFLICT DO NOTHING so existing live state
-- (e.g. an in-progress arc, a toggled watcher_sleep) is never clobbered.

begin;

-- Settings the spoiler-free health view + control surface read/write.
insert into public.settings (key, value) values
  ('watcher_sleep',  'false'::jsonb),
  ('api_status',     '"unknown"'::jsonb),
  ('whisper_status', '"ok"'::jsonb)
on conflict (key) do nothing;

-- The single arc_state row (id = 1, enforced by the check constraint).
insert into public.arc_state (id, current_act, gates, flags) values
  (1, 1, '{}'::jsonb, '{}'::jsonb)
on conflict (id) do nothing;

commit;


-- ============================================================
-- FILE: dashboard/supabase/migrations/0003_lockdown.sql
-- ============================================================

-- The Observance (dashboard) — 0003_lockdown.sql
-- SECURITY corrective (audit, CRITICAL). 0001_init.sql created an `authenticated_all` policy
-- (`for all to authenticated using(true)`) + blanket table/sequence grants over all 12 spoiler
-- tables. Sign-in is an OPEN magic-link flow, so ANY signed-in user could read/write those tables
-- directly via PostgREST (anon key + their JWT), bypassing the ADMIN_EMAILS allowlist — which only
-- gates the dashboard's OWN server actions, not direct REST calls.
--
-- The dashboard reads/writes these tables EXCLUSIVELY through the server-side service-role client
-- behind isAdmin() (author/actions.ts + author/page.tsx, re-gated in the same audit pass). So the
-- `authenticated` role needs NO access to them. This drops the blanket policy + grants; RLS stays
-- enabled (from 0001), so with no authenticated policy and no grants, only service_role (which
-- bypasses RLS) can reach them. The spoiler-FREE public VIEWS (anon) keep their own grants — the
-- public /status page is unaffected.
--
-- Idempotent. Apply AFTER 0001_init.sql + 0002_seed.sql. Run as service_role / owner.

begin;

do $$
declare
  t text;
begin
  foreach t in array array[
    'players', 'dossiers', 'custom_compliance', 'heatmap_cells', 'bases',
    'whisper_budgets', 'whisper_events', 'bond_ledger', 'arc_state',
    'beat_queue', 'event_log', 'settings'
  ]
  loop
    execute format('drop policy if exists "authenticated_all" on public.%I;', t);
    execute format('revoke all on public.%I from authenticated;', t);
    execute format('revoke all on public.%I from anon;', t);
  end loop;
end;
$$;

-- Sequences too (insert paths used them); service_role bypasses, anon views don't need them.
revoke all on all sequences in schema public from authenticated;
revoke all on all sequences in schema public from anon;

commit;


-- ============================================================
-- FILE: discord/supabase/migrations/0003_discord.sql
-- ============================================================

-- The Observance — Discord service schema
-- 0003_discord.sql
--
-- The Discord bot connects with the service_role key (server-side only), which
-- BYPASSES RLS. It links Discord users to existing Minecraft players and reads
-- pre-authored whisper hints.
--
-- Security model (consistent with 0001_init.sql):
--   * RLS is enabled on every new table.
--   * service_role bypasses RLS — the bot can do anything.
--   * NO anon / authenticated policies are added for `hints` — it is service-role
--     ONLY (the pre-authored hint bodies are spoilers and never reach the public
--     or the dashboard's authenticated admins through this table).
--
-- Everything runs in the `public` schema.

begin;

-- ---------------------------------------------------------------------------
-- players.discord_id — links a Discord user to a Minecraft player.
-- Nullable: a player may exist without ever linking Discord.
-- Unique: a Discord account maps to at most one player.
-- ---------------------------------------------------------------------------

alter table public.players
  add column if not exists discord_id text unique;

-- ---------------------------------------------------------------------------
-- hints — the PRE-AUTHORED whisper hints, keyed by (puzzle_key, tier).
-- Seeded later from the sealed arc (NOT committed to code). The bot only READS
-- this table; it is left empty here.
-- ---------------------------------------------------------------------------

create table if not exists public.hints (
  id         bigserial primary key,
  puzzle_key text not null,
  tier       int  not null,
  body       text not null,
  unique (puzzle_key, tier)
);

-- Fast lookup path used by the bot: getHint(puzzle_key, tier).
create index if not exists idx_hints_puzzle_tier
  on public.hints (puzzle_key, tier);

-- ---------------------------------------------------------------------------
-- Row Level Security — enabled, service-role ONLY.
-- No anon and no authenticated policies: only the service_role (which bypasses
-- RLS entirely) can read or write `hints`.
-- ---------------------------------------------------------------------------

alter table public.hints enable row level security;

-- Defensive: ensure no blanket grants leak from Supabase defaults.
revoke all on public.hints from anon;
revoke all on public.hints from authenticated;
revoke all on sequence public.hints_id_seq from anon;
revoke all on sequence public.hints_id_seq from authenticated;

commit;


-- ============================================================
-- FILE: discord/supabase/migrations/0004_oracle.sql
-- ============================================================

-- The Observance — Oracle schema (the non-linear clue web).
-- 0004_oracle.sql
--
-- The ORACLE is the closed loop: a player who solves a forged clue submits the
-- plaintext answer (in Discord #the-record OR on an in-world answer-sign), the
-- bot/plugin matches it against the OPEN puzzles, and — if it matches — the world
-- answers. This migration creates the authoring + resolution tables that loop
-- runs on.
--
-- DIFFICULTY: HARD, NON-LINEAR WEB. Many puzzles are `active` at once. A single
-- answer resolves to ONE of five OUTCOME TYPES (next_clue | lore | dead_end |
-- side_quest | main_beat). Multiple correct answers per puzzle are supported
-- (accepted_answers is an array). Some clues advance, some only reveal lore,
-- some are TRUE-BUT-NOT-A-DOOR dead ends (red-herring texture the watcher
-- acknowledges in voice but that leads nowhere), some open optional side quests,
-- some fire a main story beat. Authors wire ANY of these per row.
--
-- Security model (consistent with 0001_init.sql / 0003_discord.sql):
--   * RLS enabled on every new table.
--   * service_role bypasses RLS — the bot/plugin (service-role, server-side) can
--     do anything; NO anon / authenticated policies are added. `accepted_answers`
--     are spoilers and must never reach the public or the dashboard admins through
--     these tables.
--
-- Everything runs in the `public` schema.

begin;

-- ===========================================================================
-- 0. beat_queue reconciliation — additive, non-breaking.
--
-- The plugin (data/rows/BeatQueueRow.java + beats/RealBeatEnactor.java) ALREADY
-- reads `mc_uuid`, `site_id`, `priority` and writes status 'failed', and
-- fetchActionableBeats() orders by `priority`. The canonical 0001 beat_queue has
-- only `target` and a status check WITHOUT 'failed'. The oracle's `unlock` beats
-- must be enqueued in a shape the plugin can read + target, so we bring the live
-- schema up to the contract the plugin already speaks. Existing `target`-based
-- inserts (e.g. /whisper) keep working untouched.
-- ===========================================================================

alter table public.beat_queue
  add column if not exists mc_uuid  text,
  add column if not exists site_id  text,
  add column if not exists priority int;

-- Widen the status check to include 'failed' (the plugin's terminal state for a
-- beat whose enactor threw). Drop the old constraint by its default name, re-add.
do $$
begin
  if exists (
    select 1 from pg_constraint
    where conrelid = 'public.beat_queue'::regclass
      and conname  = 'beat_queue_status_check'
  ) then
    alter table public.beat_queue drop constraint beat_queue_status_check;
  end if;
end $$;

alter table public.beat_queue
  add constraint beat_queue_status_check
  check (status in ('pending','approved','firing','skipped','fired','failed'));

-- APPROVAL GATE: the plugin poller fires `status=eq.approved` ONLY, ordered by
-- priority desc, created_at asc — so `pending` beats wait for a human to approve
-- them in the dashboard (the showrunner CONFIRM mode + the Accepting trigger).
-- The dashboard, in turn, lists the `pending` beats as its approval queue. This
-- partial index covers BOTH access paths (the poller's approved read and the
-- dashboard's pending read), so both stay index-served.
create index if not exists idx_beat_queue_actionable
  on public.beat_queue (priority desc nulls last, created_at asc)
  where status in ('pending','approved');

-- ===========================================================================
-- 1. puzzles — the authored clue web. One row per forged clue.
--
-- puzzle_key is the STABLE FNV-1a id from forgeClue() (e.g. "clue_caesar_1a2b3c4d").
-- It is the SAME key hints (0003), whisper_events, and solves are addressed by, so
-- the whole loop points at one puzzle.
-- ===========================================================================

create table if not exists public.puzzles (
  -- the forgeClue() FNV-1a key — the join point for the entire web.
  puzzle_key       text primary key,

  -- author-facing label (spoiler; never shown to players in voice).
  title            text not null,

  -- normalized accepted solutions. MULTIPLE correct answers supported. Each
  -- entry MUST already be stored in normalized form (see ORACLE.md §normalize):
  -- case-folded, trimmed, internal whitespace collapsed to single spaces,
  -- punctuation stripped. The resolver normalizes the player's raw input the same
  -- way and tests set-membership against this array.
  accepted_answers text[] not null check (array_length(accepted_answers, 1) >= 1),

  -- what a correct answer DOES. The web's branching dimension:
  --   next_clue  — advances: reveals/forges the next clue (a door).
  --   lore       — reveals story/character info; NO progression (not a door).
  --   dead_end   — a TRUE answer deliberately not a door: the watcher
  --                acknowledges it in voice, it leads nowhere. red-herring texture.
  --   side_quest — opens an optional thread (a door to an off-spine branch).
  --   main_beat  — fires a main-story event/unlock (a door to the spine).
  outcome_type     text not null
                     check (outcome_type in
                       ('next_clue','lore','dead_end','side_quest','main_beat')),

  -- the resolution recipe. Shape (all keys optional unless noted):
  --   {
  --     "voice_key": "oracleNextClue",        -- which voice.ts line speaks the reply (REQUIRED)
  --     "voice_args": { "name": "...", ... }, -- optional args spread into the voice fn
  --     "next_puzzle_key": "clue_book_…",     -- for next_clue / side_quest: the puzzle this opens
  --     "set_flags": { "found_well": true },  -- optional arc_state.flags to set on solve
  --     "beat": {                             -- OPTIONAL in-world reward to enqueue (see ORACLE.md)
  --       "type": "unlock",                   --   beat_queue.type
  --       "mc_uuid": "{solver}",              --   "{solver}" placeholder → resolved to the solving player's uuid
  --       "site_id": "well_shrine",           --   optional sites.yml id
  --       "priority": 10,                     --   optional ordering hint
  --       "payload": { "step": "door_open",   --   the UnlockBeat dispatcher payload
  --                    "step_payload": { "radius": 3, "open": true } }
  --     }
  --   }
  -- dead_end rows carry voice_key only (the acknowledgement) and NO next_puzzle_key
  -- and NO beat — it is true, it is heard, it opens nothing.
  outcome_payload  jsonb not null default '{}'::jsonb,

  -- author-facing position on the web (act/rung). For ordering/visualization only;
  -- the resolver does NOT gate on it (the web is non-linear). Defaults to 0.
  movement         int not null default 0,

  -- is this puzzle OPEN for answers? The resolver only ever matches against rows
  -- where active = true. Authors flip this to stage/retire branches of the web.
  active           boolean not null default true,

  -- per-puzzle attempt cap (anti-brute-force, on top of the global rate limit).
  -- NULL = no per-puzzle cap (the global token bucket still applies). When set,
  -- a player who reaches it is met with in-voice silence/withholding, never a hint.
  max_attempts     int,

  created_at       timestamptz not null default now()
);

-- Resolver hot path: "give me the OPEN puzzles to match this answer against".
create index if not exists idx_puzzles_active
  on public.puzzles (active)
  where active = true;

-- ===========================================================================
-- 2. solves — the replay guard. One row per (puzzle, player) that resolved.
--
-- IDEMPOTENT: unique(puzzle_key, player_id) means solving the same puzzle twice
-- cannot double-fire its unlock. The resolver INSERTs here with ON CONFLICT DO
-- NOTHING *before* enqueuing the beat; only a genuinely-new insert proceeds to
-- enqueue the reward.
-- ===========================================================================

create table if not exists public.solves (
  id           bigserial primary key,

  -- which puzzle was solved.
  puzzle_key   text not null references public.puzzles(puzzle_key) on delete cascade,

  -- WHO solved it. player_id is the canonical link; mc_uuid + discord_id are
  -- denormalized for audit and for whichever surface (in-world / discord) the
  -- solve arrived on. player_id is NOT NULL (a solve is always a known keeper).
  player_id    uuid not null references public.players(id) on delete cascade,
  mc_uuid      text,
  discord_id   text,

  -- how many attempts this player made before the solve landed (audit/balance).
  attempt_count int not null default 1,

  solved_at    timestamptz not null default now(),

  -- the replay guard: one solve per puzzle per player.
  unique (puzzle_key, player_id)
);

create index if not exists idx_solves_player
  on public.solves (player_id);

-- ===========================================================================
-- 3. answer_attempts — append-only audit + rate-limit substrate.
--
-- EVERY attempt is logged (matched or not) so the resolver can enforce cooldown
-- + token bucket and so authors can see brute-force pressure. Never reveals which
-- PART was right — it records the whole normalized string and a single matched bool.
-- ===========================================================================

create table if not exists public.answer_attempts (
  id          bigserial primary key,

  -- which puzzle this attempt matched, if any. NULL when the input matched no
  -- open puzzle (ordinary chat the watcher stays silent on, or a true miss).
  puzzle_key  text references public.puzzles(puzzle_key) on delete set null,

  -- who attempted. player_id may be NULL for an unlinked discord user whose
  -- message was scanned in #the-record (we still rate-limit them by discord_id).
  player_id   uuid references public.players(id) on delete set null,
  mc_uuid     text,
  discord_id  text,

  -- where it came from: 'discord' (#the-record scan or future command) or 'world'
  -- (an in-world answer-sign). Used to scope rate limits per surface if desired.
  surface     text check (surface in ('discord','world')),

  -- the player's exact input (audit) and its normalized form (what was matched).
  raw         text,
  normalized  text,

  -- did `normalized` hit an accepted_answers entry of an OPEN puzzle?
  matched     boolean not null default false,

  at          timestamptz not null default now()
);

-- Rate-limit lookups: "how many attempts has this player made in the last window?"
-- Two indexes — by linked player, and by raw discord_id for unlinked scanners.
create index if not exists idx_answer_attempts_player_at
  on public.answer_attempts (player_id, at desc);

create index if not exists idx_answer_attempts_discord_at
  on public.answer_attempts (discord_id, at desc);

create index if not exists idx_answer_attempts_mc_at
  on public.answer_attempts (mc_uuid, at desc);

-- ===========================================================================
-- 4. Row Level Security — enabled, service-role ONLY (spoiler tables).
-- No anon / authenticated policies: only service_role (which bypasses RLS) reads
-- or writes these. Defensive revokes mirror 0003_discord.sql.
-- ===========================================================================

alter table public.puzzles         enable row level security;
alter table public.solves          enable row level security;
alter table public.answer_attempts enable row level security;

revoke all on public.puzzles         from anon;
revoke all on public.puzzles         from authenticated;
revoke all on public.solves          from anon;
revoke all on public.solves          from authenticated;
revoke all on public.answer_attempts from anon;
revoke all on public.answer_attempts from authenticated;

revoke all on sequence public.solves_id_seq          from anon;
revoke all on sequence public.solves_id_seq          from authenticated;
revoke all on sequence public.answer_attempts_id_seq from anon;
revoke all on sequence public.answer_attempts_id_seq from authenticated;

commit;


-- ============================================================
-- FILE: discord/supabase/migrations/0005_threads.sql
-- ============================================================

-- The Observance — 0005_threads.sql
-- The reconstruction layer (the Recovery Archive), the side-quest breadth, the
-- discover-by-punishment custom state, and the NPC dialogue state. All additive; runs
-- after 0004_oracle.sql. Closes red-team blocker B-7 (the thread-layer coverage skeleton)
-- and the INTEGRATION §5 data-model additions.
--
-- Security model (identical to 0004): RLS enabled on every new table; service_role bypasses
-- it; NO anon / authenticated policies (these carry spoiler structure + per-player state).
--
-- Everything in the `public` schema. Idempotent (create … if not exists, add column if not
-- exists, on conflict do nothing) — safe to re-run.

begin;

-- ===========================================================================
-- 1. threads — the five reconstruction threads (the Recovery Archive columns).
--    Progress = these filling in, NOT a step counter (the rumor→verify skeleton).
--    Canonical keys mirror forge/canon.ts THREADS; a thread-coverage self-test asserts
--    every puzzles.thread_key / thread_cards.thread_key is one of these.
-- ===========================================================================

create table if not exists public.threads (
  thread_key      text primary key,            -- who | place | happened | surface | human
  label           text not null,               -- player-facing column title
  color           text not null,               -- card tint (amber/green/red/grey/black)
  sort_order      int  not null default 0,
  created_at      timestamptz not null default now()
);

-- Seed the five canonical threads (the questions the whole game answers).
insert into public.threads (thread_key, label, color, sort_order) values
  ('who',      'who they were',              'amber', 1),
  ('place',    'what this place was',        'green', 2),
  ('happened', 'what happened',              'red',   3),
  ('surface',  'what is on the surface',     'grey',  4),
  ('human',    'were they human',            'black', 5)
on conflict (thread_key) do nothing;

-- ===========================================================================
-- 2. thread_cards — the ship-log: every find is a place-anchored card that clusters
--    under a thread. Rumor cards flip to verified/contradicted on arrival; conditional
--    reveals expand once referenced cards are found. Authored content lands here.
-- ===========================================================================

create table if not exists public.thread_cards (
  card_key            text primary key,
  thread_key          text not null references public.threads(thread_key) on delete cascade,
  title               text not null,
  -- the in-character body comes from voice.ts / the corpus via a key, never inline english.
  body_voice_key      text,
  -- where in the world this card is anchored (a sites.yml id), if any.
  anchor_site_id      text,
  -- 'rumor' = heard secondhand (a dotted line to an unvisited place); 'explore' = verified
  -- firsthand on-site. Arriving can flip a rumor to 'verified' or 'contradicted'.
  card_kind           text not null default 'explore'
                        check (card_kind in ('rumor','explore','verified','contradicted')),
  -- cards this one references (the citation web); a conditional reveal expands once these
  -- are all found (alt_text_condition names the gate).
  references_card_key text[] not null default '{}',
  -- the solve (puzzle_key) that surfaces this card, if it is solve-gated.
  revealed_by_solve   text,
  -- the named condition under which alt/expanded text unlocks (e.g. 'found:warden-tag').
  alt_text_condition  text,
  sort_order          int not null default 0,
  created_at          timestamptz not null default now()
);

create index if not exists idx_thread_cards_thread on public.thread_cards (thread_key, sort_order);

-- ===========================================================================
-- 3. side_quests — the breadth layer (off-spine threads that GATE NOTHING; they pay
--    lore/atmosphere/items/time). The longevity engine's non-spine volume.
-- ===========================================================================

create table if not exists public.side_quests (
  quest_key       text primary key,
  thread_key      text references public.threads(thread_key) on delete set null,
  -- the puzzle/row that opens it (a side_quest-outcome node), if any.
  entry_puzzle_key text,
  -- what it pays (free-text authoring note; the actual reward is the node's outcome).
  reward          text,
  -- BREADTH INVARIANT: a side quest must never gate spine progress.
  gates_progress  boolean not null default false check (gates_progress = false),
  -- tier: ambient (just found) | rumored (pointed at, verify) | keyed (needs a side-cipher).
  tier            text not null default 'ambient'
                    check (tier in ('ambient','rumored','keyed')),
  -- rough authored play-minutes (the HOURS ledger; red-team B-1: budget time, not nodes).
  est_minutes     int not null default 0,
  created_at      timestamptz not null default now()
);

-- ===========================================================================
-- 4. punishment_state — the spine of discover-by-punishment (Req 3). Per (player, way):
--    the custom pass escalates a soft, reversible toll on repeated transgression until the
--    player DECIPHERS the way (from a teaching surface) and stops. NOT a hard punishment —
--    tolls take warmth, not progress (INV-8).
-- ===========================================================================

create table if not exists public.punishment_state (
  id                 bigserial primary key,
  player_id          uuid not null references public.players(id) on delete cascade,
  -- canonical the_-prefixed custom key (forge/canon.ts CUSTOM_KEYS).
  custom_key         text not null,
  transgression_count int not null default 0,
  last_toll_at       timestamptz,
  -- 0 none, 1 deniable(stage A), 2 named(stage B / warn). escalates with repetition.
  toll_tier          int not null default 0,
  -- true once the player has performed the way (learned it); the toll then clears.
  deciphered         boolean not null default false,
  -- which in-world clue teaches this way (a sites.yml id / doc) — so the loop is fair.
  teaching_site_id   text,
  updated_at         timestamptz not null default now(),
  unique (player_id, custom_key)
);

create index if not exists idx_punishment_player on public.punishment_state (player_id);

-- ===========================================================================
-- 5. npc_dialogue_state + npc_quests — per-player NPC conversation + fetch/return state,
--    so surface NPCs (Citizens2) remember and branch on the dossier. The Iss tree flips
--    warm→cold on arc_state.flags.iss_caught.
-- ===========================================================================

create table if not exists public.npc_dialogue_state (
  id          bigserial primary key,
  player_id   uuid not null references public.players(id) on delete cascade,
  npc_key     text not null,              -- aro | wenna | coll | dob | old-pell | …
  -- conversation cursor + any per-NPC flags (jsonb so dialogue trees evolve without migration).
  state       jsonb not null default '{}'::jsonb,
  updated_at  timestamptz not null default now(),
  unique (player_id, npc_key)
);

create table if not exists public.npc_quests (
  id          bigserial primary key,
  player_id   uuid not null references public.players(id) on delete cascade,
  quest_key   text not null,
  status      text not null default 'offered'
                check (status in ('offered','active','done','failed')),
  updated_at  timestamptz not null default now(),
  unique (player_id, quest_key)
);

create index if not exists idx_npc_dialogue_player on public.npc_dialogue_state (player_id);
create index if not exists idx_npc_quests_player    on public.npc_quests (player_id);

-- ===========================================================================
-- 6. puzzles column adds — tag each node to a thread + (optionally) the way it teaches.
--    Lets the Recovery Archive cluster a solved node's card, and links the cipher↔custom
--    layers. Additive + nullable; existing rows unaffected.
-- ===========================================================================

alter table public.puzzles
  add column if not exists thread_key    text references public.threads(thread_key),
  add column if not exists teaches_custom text;

create index if not exists idx_puzzles_thread on public.puzzles (thread_key) where thread_key is not null;

-- ===========================================================================
-- 7. Row Level Security — service-role ONLY (spoiler structure + per-player state).
-- ===========================================================================

alter table public.threads            enable row level security;
alter table public.thread_cards       enable row level security;
alter table public.side_quests        enable row level security;
alter table public.punishment_state   enable row level security;
alter table public.npc_dialogue_state enable row level security;
alter table public.npc_quests         enable row level security;

revoke all on public.threads            from anon;  revoke all on public.threads            from authenticated;
revoke all on public.thread_cards       from anon;  revoke all on public.thread_cards       from authenticated;
revoke all on public.side_quests        from anon;  revoke all on public.side_quests        from authenticated;
revoke all on public.punishment_state   from anon;  revoke all on public.punishment_state   from authenticated;
revoke all on public.npc_dialogue_state from anon;  revoke all on public.npc_dialogue_state from authenticated;
revoke all on public.npc_quests         from anon;  revoke all on public.npc_quests         from authenticated;

revoke all on sequence public.punishment_state_id_seq   from anon;  revoke all on sequence public.punishment_state_id_seq   from authenticated;
revoke all on sequence public.npc_dialogue_state_id_seq from anon;  revoke all on sequence public.npc_dialogue_state_id_seq from authenticated;
revoke all on sequence public.npc_quests_id_seq         from anon;  revoke all on sequence public.npc_quests_id_seq         from authenticated;

commit;


-- ============================================================
-- FILE: discord/supabase/migrations/0006_requires_flags.sql
-- ============================================================

-- The Observance — 0006_requires_flags.sql
-- THE KEYSTONE. Adds the one column the entire non-linear progression depends on and
-- that no prior migration ever created: `puzzles.requires_flags`.
--
-- Why this file is the single most important fix in the overhaul (see design/OVERHAUL.md §2):
-- the seeds already author a complete, internally-consistent flag-gate — metapuzzle_seed.sql
-- §2 sets requires_flags on every back-half row and flips them active, and progression_seed.sql
-- gates the Nether/End lanes the same way. BUT every one of those UPDATEs sits inside a
--   `do $$ begin if exists (… column_name = 'requires_flags') then … else raise notice … end $$;`
-- guard, because the column didn't exist. So they all silently no-op: nine M4/Seventh rows that
-- ship active=false stay dark forever, and base-docket-reread-auto ships active=true meant to be
-- HELD CLOSED by a gate that isn't there, so it leaks its M4 answers from minute one.
--
-- This migration creates the column. After it lands, RE-RUN the seeds (puzzles_seed.sql,
-- metapuzzle_seed.sql, progression_seed.sql) so the guarded activation lane takes effect — the
-- guards now see the column and apply instead of `raise notice`. The whole back half lights up.
--
-- THE GATE CONTRACT (the storylet precondition system; OVERHAUL.md §3):
--   A row is OPEN  ⟺  active = true  AND  every key in requires_flags is truthy in arc_state.flags.
--   `getOpenPuzzles` (discord/src/db/repo.ts) and the Java OracleResolver.firstMatch BOTH AND-test
--   it. An empty `{}` (the default) means "no gate" — so every existing ungated row is unchanged.
--
-- Security model (identical to 0004/0005): RLS already enabled on puzzles; service_role bypasses;
-- no anon/authenticated policies. Additive + idempotent (add column if not exists) — safe to re-run.

begin;

-- ===========================================================================
-- 1. puzzles.requires_flags — the storylet precondition. A flat jsonb object of
--    { flag_key: true } that must ALL be truthy in arc_state.flags for the row to open.
--    Default '{}' = ungated (the open condition collapses to just active=true), so adding
--    the column changes the behavior of NO existing row until a seed sets a non-empty value.
-- ===========================================================================

alter table public.puzzles
  add column if not exists requires_flags jsonb not null default '{}'::jsonb;

comment on column public.puzzles.requires_flags is
  'Storylet gate (OVERHAUL.md §3): a flat {flag:true} object; the row is open iff active=true '
  'AND every key here is truthy in arc_state.flags. Default {} = ungated. AND-tested by '
  'getOpenPuzzles (TS) and OracleResolver.firstMatch (Java). Keep FLAT — the merge is shallow.';

-- A partial expression index is unnecessary: `puzzles` is a tiny table read in full each resolve
-- (getOpenPuzzles selects all active rows, then the app AND-tests requires_flags against the single
-- arc_state row's flags). No query filters on requires_flags in SQL, so no index is added here.

-- ===========================================================================
-- 2. observance_merge_arc_flags(p_flags) — ATOMIC shallow merge of the single
--    arc_state.flags blob. Kills the read-modify-write clobber in repo.setArcFlags:
--    a concurrent Discord solve + in-world solve (or two Discord solves) each doing
--    SELECT-then-UPDATE could drop one set's keys; the jsonb `||` union performed
--    server-side in ONE statement cannot. Right operand wins on key conflict — exactly
--    right for our flat {flag:true} shape (DOSSIER #A2). Flags MUST stay flat (the merge
--    is shallow; a nested object would be wholesale-overwritten, not deep-merged).
-- ===========================================================================

create or replace function public.observance_merge_arc_flags(p_flags jsonb)
returns jsonb
language sql
security definer
set search_path = public
as $$
  update public.arc_state
     set flags = flags || coalesce(p_flags, '{}'::jsonb),
         updated_at = now()
   where id = 1
  returning flags;
$$;

comment on function public.observance_merge_arc_flags(jsonb) is
  'Atomic shallow merge into arc_state.flags (id=1): flags = flags || p_flags in one '
  'statement (no read-modify-write clobber). Keep the flags object FLAT. Called by '
  'repo.setArcFlags via .rpc().';

-- Lock the function down to service_role only (the bot/showrunner run as service_role;
-- there is no anon/authenticated path that should mutate the arc). REVOKE the default
-- PUBLIC EXECUTE that `create function` grants, then GRANT to service_role explicitly.
revoke all on function public.observance_merge_arc_flags(jsonb) from public;
grant execute on function public.observance_merge_arc_flags(jsonb) to service_role;

commit;


-- ============================================================
-- FILE: discord/supabase/migrations/0007_answer_kind.sql
-- ============================================================

-- The Observance — 0007_answer_kind.sql
-- Adds `puzzles.answer_kind` — the coarse resolution modality of a puzzle's answer, so the
-- seed can DECLARE (and the tooling can reason about) which rows are typed-phrase solves vs
-- which are produced by an in-world PLUGIN listener that sets the puzzle's flag directly.
--
-- Why this column exists (design/PUZZLE-DESIGNS.md §1 / PUZZLES.md §4): the diverse-expansion
-- puzzles span many modalities. Some resolve by a TYPED phrase the resolver matches against
-- accepted_answers (answer_kind='phrase' — today's only resolver path, and the DEFAULT). Others
-- resolve by a body action, a deposited object, a spoken line, or an on-site bearing — those are
-- detected by a plugin PRODUCER listener that posts an opaque sentinel token OR sets the puzzle's
-- flag directly. The resolver needs NO new branch for the non-typed kinds: it keeps matching
-- normalized phrases / opaque tokens exactly as it does today. answer_kind is DECLARATIVE metadata
-- that records the intent and lets a later plugin round know which rows need a producer.
--
--   answer_kind ∈ { phrase | coords | url_token | behavior | object | spoken | code | none }
--     phrase     — typed free text matched against accepted_answers (DEFAULT; the resolver path)
--     coords     — an on-site destination WORD found by following a bearing (typed; INV-14)
--     url_token  — a decoded record-website path token (typed)
--     code       — a lock/dial/comparator combination the plugin reads (plugin-produced)
--     behavior   — a body action (bow / stand-at-anchor / silence) the plugin detects
--     object     — a container-content / deposit the plugin detects
--     spoken     — a voice-chat line the Observer Engine hears
--     none       — a comprehension beat with nothing to submit (the world reacts)
--
-- ADDITIVE + IDEMPOTENT: `add column if not exists … default 'phrase'` — every existing row is
-- unaffected (they are all typed-phrase solves, the historical implicit default). Safe to re-run.
--
-- Security model (identical to 0004/0005/0006): RLS already enabled on puzzles; service_role
-- bypasses; no anon/authenticated policies.

begin;

alter table public.puzzles
  add column if not exists answer_kind text not null default 'phrase';

comment on column public.puzzles.answer_kind is
  'The answer modality (design/PUZZLE-DESIGNS.md §1): phrase|coords|url_token|code|behavior|'
  'object|spoken|none. DECLARATIVE metadata. phrase/coords/url_token are typed and matched by '
  'the resolver against accepted_answers; code/behavior/object/spoken are produced by a plugin '
  'listener that posts the sentinel token or sets the flag directly (no new resolver branch); '
  'none is a comprehension beat. Default ''phrase'' = the historical typed-solve path.';

commit;


-- ============================================================
-- FILE: discord/supabase/migrations/0008_requires_quorum.sql
-- ============================================================

-- The Observance — 0008_requires_quorum.sql
-- THE ROSTER-QUORUM COLUMN (S-F roster guard). Adds the one nullable column the showrunner's
-- convergence guard reads: `puzzles.requires_quorum`.
--
-- Why (design/OVERHAUL.md dynamic-roster invariant + decide.ts rosterCanClose): a handful of beats
-- are genuine CONVERGENCES — they cannot be closed by a lone player because the in-world detection is
-- a group act (everyone present bows as one; three hands on three surfaces at once; the group walks
-- the map; an asymmetric co-op vault). The showrunner must NOT drip such a thread to a roster too
-- small to close it — surfacing a convergence the present group cannot possibly complete is the
-- dead-air failure the reshape fixes. `decide.rosterCanClose(p, s)` already implements the guard
-- (excludes a row when requires_quorum > activeRosterSize); it was inert because no column fed it.
--
-- THE CONTRACT (decide.ts / snapshot.ts / types.ts):
--   requires_quorum NULL  ⟺  no quorum gate — the row is always eligible for the drip (back-compat:
--                            every existing row keeps NULL, so its drip eligibility is unchanged).
--   requires_quorum = N   ⟺  the node opens to the drip only once >= N active players are present
--                            (the SAME active-set the plugin's AcceptingRiteListener uses for
--                            effectiveQuorum = min(configQuorum, activeRosterSize)). snapshot.ts
--                            selects this column onto SnapshotPuzzle.requiresQuorum; the guard is a
--                            no-op for any row that leaves it NULL.
--
-- Security model (identical to 0004/0005/0006): RLS already enabled on puzzles; service_role
-- bypasses; no anon/authenticated policies. Additive + idempotent (add column if not exists) — safe
-- to re-run and changes the behavior of NO existing row until a seed sets a non-NULL value.

begin;

-- ===========================================================================
-- 1. puzzles.requires_quorum — the convergence gate for the showrunner drip.
--    Nullable integer, default NULL = no quorum gate. Adding the column changes the
--    behavior of NO existing row (the guard no-ops on NULL); a later seed sets it on
--    the genuine convergence rows (metapuzzle_seed.sql §5).
-- ===========================================================================

alter table public.puzzles
  add column if not exists requires_quorum integer;

comment on column public.puzzles.requires_quorum is
  'Convergence quorum for the showrunner drip (decide.rosterCanClose): the minimum number of ACTIVE '
  'players that must be present before this node is surfaced in the clue-drip. NULL = no quorum gate '
  '(the default; the guard no-ops). Read by snapshot.ts onto SnapshotPuzzle.requiresQuorum and '
  'compared against Snapshot.activeRosterSize (readActiveRoster().length). Does NOT gate resolution '
  '(that is requires_flags / the in-world detection) — only the curatorial drip.';

commit;


-- ============================================================
-- FILE: discord/supabase/migrations/0009_observations.sql
-- ============================================================

-- The Observance — 0009_observations.sql
-- The Observer Tier-1 store: grounded VERBATIM captures the world may sparsely quote back ("it heard
-- you say it"). Tier-0 (behavior — Tier0Observation / reports.ts) needs none of this and is untouched;
-- this is the WORDS tier, the one that must be handled with the most care.
--
-- THE DISCIPLINE THIS TABLE ENFORCES (the mandate: grounded-only · sparse · consent · degrade to
-- silence, never fabricate):
--   * GROUNDED: `text` is a REAL captured utterance, stored verbatim. The weaponizer only ever quotes
--     what is literally here — it never composes or paraphrases a "quote" (that would be fabrication).
--   * SET-ONCE USE: `weaponized_at` is null until the line has been surfaced, then stamped, so a quote
--     is used at most once — sparse by construction, never a nagging replay.
--   * CONSENT: capture is gated TWICE. Globally by settings.observer_capture (default OFF — nothing is
--     stored until the operator turns it on), and per-player by players.observer_opt_out (a person can
--     say "don't keep my words" and the capture skips them). The group/operator handles the pre-launch
--     consent conversation; this field is the emergency individual floor.
--   * PRIVATE: RLS service-role only. NEVER anon-readable (unlike the archive) — this is PII. No view,
--     no grant. The public Record can never surface a captured utterance.
--
-- Additive + idempotent. Apply after 0001 (players/settings) exists. Shared DB.

begin;

-- 1. observations — one grounded captured utterance. player_id is the linked identity (nullable — an
--    unlinked speaker is kept by mc_uuid only, and is never weaponized until linked). source names the
--    surface it came from; context is provenance (channel / where); weaponized_at is the set-once "used".
create table if not exists public.observations (
  id            bigserial primary key,
  player_id     uuid references public.players(id) on delete cascade,
  mc_uuid       text,
  source        text not null check (source in ('discord', 'chat', 'voice')),
  text          text not null,
  context       text,
  observed_at   timestamptz not null default now(),
  weaponized_at timestamptz
);

create index if not exists idx_observations_unused
  on public.observations (observed_at)
  where weaponized_at is null;

alter table public.observations enable row level security;
-- No policy, no grant: deny-by-default. Only the service role (the capturer + the weaponizer) touches it.
revoke all on public.observations from anon, authenticated;

-- 2. per-player opt-out — the individual consent floor. Default false = kept (group consent); a person
--    who opts out is never captured and never quoted.
alter table public.players
  add column if not exists observer_opt_out boolean not null default false;

-- 3. the global capture switch — OFF until the operator enables it (nothing is stored before then).
insert into public.settings (key, value)
  values ('observer_capture', 'false'::jsonb)
  on conflict (key) do nothing;
insert into public.settings (key, value)
  values ('voice_capture', 'false'::jsonb)
  on conflict (key) do nothing;

commit;


-- ============================================================
-- FILE: discord/supabase/migrations/0010_answer_attempts_web_rate_limit.sql
-- ============================================================

-- 0010_answer_attempts_web_rate_limit.sql — a real anonymous-flood guard for the record website.
--
-- HISTORICAL WHY. The retired record website answer-inscribe endpoint rate-limited
-- a KNOWN keeper by player_id (countRecentAttempts), but an UNRESOLVED name has no player_id to key on —
-- so unknown-name submissions were completely unthrottled (a cheap DB-write-spam vector on a public,
-- unauthenticated POST route; not a spoiler leak, since the response is uniform regardless). The web
-- resolver also logged every attempt under surface='discord' (the CHECK constraint's only non-'world'
-- option at the time), which its own comment already flagged as a stopgap: "A future migration could
-- add a 'web' surface." This is that migration.
--
-- V5 STATUS. The arbitrary-name website inscription endpoint is permanently closed (HTTP 410), and
-- the six fixed Copperline website nodes use the prerequisite-guarded V5 recording RPC instead. Keep
-- this additive migration in the ordered bundle so existing databases and historical audit rows remain
-- schema-compatible; it does not re-enable the retired endpoint.
--
-- WHAT. (1) Widen the surface CHECK to add 'web', so the record website's attempts are logged under
-- their own real surface instead of borrowing 'discord' (which the Discord bot's own unlinked-user
-- rate-limiting also reads — the two were at risk of quietly sharing a bucket). (2) Add a nullable
-- ip_hash column + a partial index, so an unresolved-name submission can be throttled by a hash of the
-- request's client IP instead of skipping rate-limiting entirely. Never a raw IP at rest.
--
-- Fully IDEMPOTENT + additive: drop/re-add the constraint (safe re-run, matches 0009's own idiom),
-- add-column-if-not-exists, create-index-if-not-exists. Safe on a fresh DB or a re-run.

alter table if exists public.answer_attempts
  drop constraint if exists answer_attempts_surface_check;

alter table if exists public.answer_attempts
  add constraint answer_attempts_surface_check
  check (surface in ('discord', 'world', 'web'));

alter table if exists public.answer_attempts
  add column if not exists ip_hash text;

-- Partial: only unresolved (player_id null) rows ever need an ip_hash lookback, so this stays small.
create index if not exists idx_answer_attempts_iphash_at
  on public.answer_attempts (ip_hash, at desc)
  where player_id is null and ip_hash is not null;


-- ============================================================
-- FILE: discord/supabase/migrations/0011_showrunner_lock.sql
-- ============================================================

-- 0011_showrunner_lock.sql — an atomic lease lock so two overlapping showrunner cron ticks can never
-- run concurrently.
--
-- WHY. `showrunner/state.ts`'s readState()/writeState() do a plain SELECT then a plain upsert of the
-- WHOLE `showrunner_state` jsonb row (every high-water mark this codebase's idempotency depends on —
-- dripped_keys, reported_customs, unlit_deep_last_reported_at, finale_posted, and a dozen more — lives
-- on this one row). That is the exact read-modify-write clobber `observance_merge_arc_flags` (0006) was
-- built to kill for `arc_state.flags` — but this row never got the same fix. If the recovery cron schedule
-- is ever shorter than a run's worst-case duration (a slow external call — Observer Tier-2's LLM,
-- Discord's API), two `main()` invocations can genuinely overlap: both read the same stale state, both
-- decide independently, and whichever writes last silently discards the other's advances — at best a
-- lost high-water mark (something re-fires next tick that shouldn't), at worst a real duplicate post
-- (unlit-deep.run.ts posts to Discord BEFORE writing its mark, so two overlapping runs could both post
-- the same toll). No code change here touches the many individual high-water-mark call sites — this
-- closes the whole class at its one root cause: overlapping runs.
--
-- WHAT. A lease-based compare-and-swap lock stored as one more row on the existing `settings` table (no
-- new table). `showrunner_try_acquire_lock` atomically sets `locked_at = now()` ONLY if the lock is free
-- or its lease has expired (a crashed run that never released is a stale lease, not a permanent
-- deadlock — self-healing, no manual unstick needed). `showrunner_release_lock` clears it. Both are
-- `security definer`, `service_role`-only, matching 0006's `observance_merge_arc_flags` convention
-- exactly. `--dry-run` (writes nothing, meant to be safely run any time as a diagnostic) never touches
-- the lock at all — only a real tick contends for it.
--
-- Additive + idempotent: `create or replace function`, `insert ... on conflict do nothing`. Safe on a
-- fresh DB or a re-run.

create or replace function public.showrunner_try_acquire_lock(p_lease_seconds int default 600)
returns boolean
language plpgsql
security definer
set search_path = public
as $$
declare
  v_rows int;
begin
  insert into public.settings (key, value)
    values ('showrunner_lock', jsonb_build_object('locked_at', null))
    on conflict (key) do nothing;

  update public.settings
     set value = jsonb_build_object('locked_at', now()),
         updated_at = now()
   where key = 'showrunner_lock'
     and (
       value->>'locked_at' is null
       or (value->>'locked_at')::timestamptz < now() - make_interval(secs => p_lease_seconds)
     );

  get diagnostics v_rows = row_count;
  return v_rows > 0;
end;
$$;

comment on function public.showrunner_try_acquire_lock(int) is
  'Atomic lease lock: acquires the showrunner tick lock iff free or the previous lease expired '
  '(p_lease_seconds, default 600s — a crashed run self-heals, never a permanent deadlock). Returns '
  'true if THIS call acquired it. Called by run.ts before a real (non-dry-run) tick.';

create or replace function public.showrunner_release_lock()
returns void
language sql
security definer
set search_path = public
as $$
  update public.settings
     set value = jsonb_build_object('locked_at', null),
         updated_at = now()
   where key = 'showrunner_lock';
$$;

comment on function public.showrunner_release_lock() is
  'Releases the showrunner tick lock. Called in a finally block so a thrown error still frees it '
  '(the lease timeout is the backstop if release itself never runs).';

revoke all on function public.showrunner_try_acquire_lock(int) from public;
revoke all on function public.showrunner_release_lock() from public;
grant execute on function public.showrunner_try_acquire_lock(int) to service_role;
grant execute on function public.showrunner_release_lock() to service_role;


-- ============================================================
-- FILE: discord/supabase/migrations/0012_world_paste_ledger.sql
-- ============================================================

-- The Observance - durable world paste ledger.
-- 0012_world_paste_ledger.sql
--
-- The plugin's optional FAWE schematic path calls SupabaseClient.claimPasteLedger()
-- before pasting a large single-use set-piece. Without this table, that path compiles
-- but fails its durable cross-restart idempotency guard at runtime.

begin;

create table if not exists public.world_paste_ledger (
  id         bigserial primary key,
  world      text not null,
  site_id    text not null default '',
  schematic  text not null,
  base_x     int not null,
  base_y     int not null,
  base_z     int not null,
  pasted_at  timestamptz not null default now(),
  unique (world, site_id, schematic, base_x, base_y, base_z)
);

alter table public.world_paste_ledger enable row level security;

create index if not exists idx_world_paste_ledger_site
  on public.world_paste_ledger (site_id, schematic);

commit;


-- ============================================================
-- FILE: discord/supabase/migrations/0013_v5_investigations.sql
-- ============================================================

-- The Observance V5 -- ten mandatory investigations, 82 required nodes, durable receipts,
-- prerequisite-gated media, and a fine-grained phase cursor.
--
-- This migration is deliberately additive. It does not delete player accounts, consent choices,
-- solves, attempts, event logs, or operator history. Legacy authored rows gain an `active` switch so
-- the V5 seed can retire them without destroying audit evidence.

begin;

alter table public.arc_state
  add column if not exists phase_key text not null default 'c01-lost-server';

comment on column public.arc_state.current_act is
  'Coarse compatibility cursor used by the hint economy and old operational reports.';
comment on column public.arc_state.phase_key is
  'Fine-grained V5 progression cursor. Case/node gates use durable flags and receipts; this is a display cursor.';

alter table public.hints add column if not exists active boolean not null default true;
alter table public.thread_cards add column if not exists active boolean not null default true;
alter table public.side_quests add column if not exists active boolean not null default true;

create table if not exists public.investigations (
  case_key          text primary key check (case_key ~ '^C(0[1-9]|10)$'),
  ordinal           int not null unique check (ordinal between 1 and 10),
  title             text not null,
  summary           text not null,
  phase_key         text not null unique,
  unlock_flag       text,
  completion_flag   text not null unique,
  required          boolean not null default true check (required = true),
  active            boolean not null default true,
  expected_nodes    int not null check (expected_nodes > 0),
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now()
);

create table if not exists public.investigation_nodes (
  node_key          text primary key check (node_key ~ '^[A-Z]{1,2}[0-9]{2}$'),
  case_key          text not null references public.investigations(case_key) on delete restrict,
  ordinal           int not null check (ordinal > 0),
  title             text not null,
  room_id           text not null,
  modality          text not null,
  input_surface     text not null,
  prerequisite_flags text[] not null default '{}',
  completion_flag   text not null unique,
  reward            text not null,
  recovery          text not null,
  oracle_puzzle_key text references public.puzzles(puzzle_key) on delete set null,
  required          boolean not null default true check (required = true),
  active            boolean not null default true,
  metadata          jsonb not null default '{}'::jsonb,
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now(),
  unique (case_key, ordinal)
);

create index if not exists idx_investigation_nodes_case
  on public.investigation_nodes(case_key, ordinal) where active = true;
create index if not exists idx_investigation_nodes_oracle
  on public.investigation_nodes(oracle_puzzle_key) where oracle_puzzle_key is not null;

create table if not exists public.evidence_receipts (
  receipt_key       text primary key,
  node_key          text not null references public.investigation_nodes(node_key) on delete restrict,
  player_id         uuid references public.players(id) on delete set null,
  source            text not null check (source in ('world','discord','web','operator','recovery')),
  idempotency_key   text not null unique,
  payload           jsonb not null default '{}'::jsonb,
  received_at       timestamptz not null default now()
);

create index if not exists idx_evidence_receipts_node
  on public.evidence_receipts(node_key, received_at desc);

create table if not exists public.required_media (
  media_key          text primary key,
  case_key           text not null references public.investigations(case_key) on delete restrict,
  node_key           text not null references public.investigation_nodes(node_key) on delete restrict,
  media_kind         text not null check (media_kind in ('video','audio','archive')),
  title              text not null,
  delivery_url       text not null,
  filename           text not null,
  sha1               text not null check (sha1 ~ '^[0-9a-f]{40}$'),
  expected_payload   text not null,
  prerequisite_flags text[] not null default '{}',
  delivery_state     text not null default 'configured'
                     check (delivery_state in ('configured','verified','degraded','missing')),
  last_verified_at   timestamptz,
  active             boolean not null default true,
  created_at         timestamptz not null default now(),
  updated_at         timestamptz not null default now()
);

create index if not exists idx_required_media_case
  on public.required_media(case_key, node_key) where active = true;

-- One atomic, idempotent receipt function for Discord, the website, and the Paper plugin. The receipt
-- is inserted once, then its node completion flag is merged without a read/modify/write race.
create or replace function public.observance_record_evidence(
  p_receipt_key text,
  p_node_key text,
  p_source text,
  p_idempotency_key text,
  p_player_id uuid default null,
  p_payload jsonb default '{}'::jsonb
) returns boolean
language plpgsql
security definer
set search_path = public
as $$
declare
  v_flag text;
  v_case_key text;
  v_case_flag text;
  v_prerequisites text[];
  v_inserted int;
begin
  select n.completion_flag, n.case_key, i.completion_flag, n.prerequisite_flags
    into v_flag, v_case_key, v_case_flag, v_prerequisites
    from public.investigation_nodes n
    join public.investigations i on i.case_key = n.case_key
   where n.node_key = p_node_key and n.active and n.required and i.active and i.required;
  if v_flag is null then
    raise exception 'unknown or inactive V5 node: %', p_node_key;
  end if;
  if exists (
    select 1 from unnest(v_prerequisites) as required_flag
    cross join public.arc_state a
    where a.id = 1 and not coalesce((a.flags ->> required_flag)::boolean, false)
  ) then
    raise exception 'prerequisites not satisfied for V5 node: %', p_node_key;
  end if;

  insert into public.evidence_receipts
    (receipt_key, node_key, player_id, source, idempotency_key, payload)
  values
    (p_receipt_key, p_node_key, p_player_id, p_source, p_idempotency_key, coalesce(p_payload, '{}'::jsonb))
  on conflict (idempotency_key) do nothing;
  get diagnostics v_inserted = row_count;

  if v_inserted > 0 then
    update public.arc_state
       set flags = coalesce(flags, '{}'::jsonb) || jsonb_build_object(v_flag, true),
           updated_at = now()
     where id = 1;

    -- A case closes only when every one of its mandatory node flags is durable. This is especially
    -- important for C03: its six affidavit lanes finish in parallel, so no arbitrary keeper node is
    -- allowed to masquerade as "the last" one.
    if not exists (
      select 1
        from public.investigation_nodes n
        cross join public.arc_state a
       where n.case_key = v_case_key and n.active and n.required and a.id = 1
         and not coalesce((a.flags ->> n.completion_flag)::boolean, false)
    ) then
      update public.arc_state
         set flags = coalesce(flags, '{}'::jsonb) || jsonb_build_object(v_case_flag, true),
             phase_key = coalesce(
               (select phase_key from public.investigations where ordinal =
                 (select least(10, ordinal + 1) from public.investigations where case_key = v_case_key)),
               phase_key
             ),
             updated_at = now()
       where id = 1;
    end if;
  end if;
  return v_inserted > 0;
end;
$$;

-- Spoiler-bearing base tables remain service-role only. Public projections are defined in the
-- dashboard migration after the V5 schema exists.
alter table public.investigations enable row level security;
alter table public.investigation_nodes enable row level security;
alter table public.evidence_receipts enable row level security;
alter table public.required_media enable row level security;

revoke all on public.investigations from anon, authenticated;
revoke all on public.investigation_nodes from anon, authenticated;
revoke all on public.evidence_receipts from anon, authenticated;
revoke all on public.required_media from anon, authenticated;
revoke all on function public.observance_record_evidence(text,text,text,text,uuid,jsonb)
  from public, anon, authenticated;
grant execute on function public.observance_record_evidence(text,text,text,text,uuid,jsonb) to service_role;

commit;


-- ============================================================
-- FILE: discord/supabase/migrations/0014_atomic_identity_link.sql
-- ============================================================

-- The Observance — compatibility retirement for the former claim-first identity RPC
-- 0014_atomic_identity_link.sql
--
-- An earlier working-tree draft introduced a three-argument claim function that knew the shared
-- Copperline callback but had no per-player Minecraft proof. It must never be published or granted,
-- even transiently. 0015 creates the only production identity flow with a one-time hashed proof.

begin;

drop function if exists public.observance_claim_identity_handoff(text,text,text);

commit;


-- ============================================================
-- FILE: discord/supabase/migrations/0015_identity_proof_of_control.sql
-- ============================================================

-- The Observance — short-lived Minecraft proof-of-control for Discord identity binding
-- 0015_identity_proof_of_control.sql
--
-- The four-digit Copperline callback is shared story evidence, not account authentication.  A
-- Discord user must also present a one-time code generated for their exact online Minecraft UUID.
-- Minecraft generates 60 bits of randomness and sends only its SHA-256 digest here; plaintext is
-- shown once to the player and is never stored, logged, or sent to this database.

begin;

create table if not exists public.identity_link_challenges (
  player_id uuid primary key references public.players(id) on delete cascade,
  code_hash text not null unique check (code_hash ~ '^[0-9a-f]{64}$'),
  issued_at timestamptz not null default now(),
  expires_at timestamptz not null,
  failed_attempts integer not null default 0 check (failed_attempts between 0 and 5),
  last_failed_at timestamptz,
  consumed_at timestamptz,
  consumed_by_discord_id text,
  recovered boolean not null default false,
  previous_player_id uuid references public.players(id) on delete set null,
  check (expires_at > issued_at),
  check ((consumed_at is null and consumed_by_discord_id is null)
      or (consumed_at is not null and consumed_by_discord_id is not null))
);

alter table public.identity_link_challenges enable row level security;
revoke all on public.identity_link_challenges from public, anon, authenticated;

-- Called only by the Paper plugin with its service-role credential.  One player has one current
-- challenge. Reissuing within 30 seconds leaves the still-visible previous code valid instead of
-- silently replacing it with a code the player never received.
create or replace function public.observance_issue_identity_link_challenge(
  p_mc_uuid text,
  p_code_hash text
) returns table (
  issue_state text,
  challenge_expires_at timestamptz
)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_player_id uuid;
  v_existing public.identity_link_challenges%rowtype;
  v_now timestamptz := now();
  v_expires timestamptz := now() + interval '5 minutes';
begin
  if coalesce(btrim(p_mc_uuid), '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
     or coalesce(p_code_hash, '') !~ '^[0-9a-f]{64}$' then
    return query select 'unknown'::text, null::timestamptz;
    return;
  end if;

  -- Player row first, then challenge row: the claim RPC takes locks in the same order.
  select p.id
    into v_player_id
    from public.players p
   where lower(p.mc_uuid) = lower(btrim(p_mc_uuid))
   for update;
  if not found then
    return query select 'unknown'::text, null::timestamptz;
    return;
  end if;

  select c.*
    into v_existing
    from public.identity_link_challenges c
   where c.player_id = v_player_id
   for update;
  if found and v_existing.issued_at > v_now - interval '30 seconds' then
    return query select 'rate_limited'::text, v_existing.expires_at;
    return;
  end if;

  insert into public.identity_link_challenges (
    player_id, code_hash, issued_at, expires_at, failed_attempts, last_failed_at,
    consumed_at, consumed_by_discord_id, recovered, previous_player_id
  ) values (
    v_player_id, p_code_hash, v_now, v_expires, 0, null,
    null, null, false, null
  )
  on conflict (player_id) do update set
    code_hash = excluded.code_hash,
    issued_at = excluded.issued_at,
    expires_at = excluded.expires_at,
    failed_attempts = 0,
    last_failed_at = null,
    consumed_at = null,
    consumed_by_discord_id = null,
    recovered = false,
    previous_player_id = null;

  return query select 'issued'::text, v_expires;
end;
$$;

revoke all on function public.observance_issue_identity_link_challenge(text,text)
  from public, anon, authenticated;
grant execute on function public.observance_issue_identity_link_challenge(text,text) to service_role;

-- Remove the claim-first three-argument surface. DROP IF EXISTS succeeds in both clean installs and
-- upgrades where a draft 0014 was already applied; retaining an overload would preserve a bypass.
drop function if exists public.observance_claim_identity_handoff(text,text,text);

create or replace function public.observance_claim_identity_handoff(
  p_discord_id text,
  p_mc_name text,
  p_callback text,
  p_code_hash text
) returns table (
  claim_state text,
  player_id uuid,
  mc_uuid text,
  minecraft_name text,
  linked_discord_id text,
  receipt_inserted boolean,
  recovered boolean
)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_prerequisites text[];
  v_flags jsonb;
  v_target public.players%rowtype;
  v_previous public.players%rowtype;
  v_challenge public.identity_link_challenges%rowtype;
  v_match_count integer;
  v_had_previous boolean := false;
  v_inserted boolean := false;
  v_now timestamptz := now();
begin
  -- Callback, caller, name, and proof shape are checked before locks or writes. The story callback
  -- and LS06 Orientation filing remain independent requirements; the one-time code does not replace either.
  if coalesce(p_discord_id, '') !~ '^[0-9]{5,32}$'
     or coalesce(btrim(p_mc_name), '') !~ '^[A-Za-z0-9_]{3,16}$' then
    return query select 'unknown'::text, null::uuid, null::text, null::text,
      null::text, false, false;
    return;
  end if;
  if regexp_replace(coalesce(p_callback, ''), '[^0-9]', '', 'g') <> '9137' then
    return query select 'invalid'::text, null::uuid, null::text, null::text,
      null::text, false, false;
    return;
  end if;
  if coalesce(p_code_hash, '') !~ '^[0-9a-f]{64}$' then
    return query select 'challenge'::text, null::uuid, null::text, null::text,
      null::text, false, false;
    return;
  end if;

  select n.prerequisite_flags
    into v_prerequisites
    from public.investigation_nodes n
   where n.node_key = 'LS05' and n.active and n.required;
  if not found then
    raise exception 'LS05 identity binding is absent or inactive';
  end if;
  select a.flags into v_flags from public.arc_state a where a.id = 1;
  if not found or exists (
    select 1
      from unnest(v_prerequisites) as required_flag
     where not coalesce((v_flags ->> required_flag)::boolean, false)
  ) then
    return query select 'blocked'::text, null::uuid, null::text, null::text,
      null::text, false, false;
    return;
  end if;

  perform pg_advisory_xact_lock(hashtextextended(p_discord_id, 0));

  select count(*)::integer
    into v_match_count
    from public.players p
   where lower(p.name) = lower(btrim(p_mc_name));
  if v_match_count <> 1 then
    return query select 'unknown'::text, null::uuid, null::text, null::text,
      null::text, false, false;
    return;
  end if;

  select p.*
    into v_target
    from public.players p
   where lower(p.name) = lower(btrim(p_mc_name))
   for update;

  if v_target.discord_id is not null and v_target.discord_id <> p_discord_id then
    -- The bot maps conflict, unknown, and challenge to one private response.
    return query select 'conflict'::text, null::uuid, null::text, null::text,
      null::text, false, false;
    return;
  end if;

  select c.*
    into v_challenge
    from public.identity_link_challenges c
   where c.player_id = v_target.id
   for update;
  if not found then
    return query select 'challenge'::text, null::uuid, null::text, null::text,
      null::text, false, false;
    return;
  end if;

  -- Network retries of one already-committed transaction are idempotent for ten minutes, but only
  -- for the same Discord account, same target, and exact consumed digest. No second reward or bind.
  if v_challenge.consumed_at is not null then
    if v_challenge.consumed_by_discord_id = p_discord_id
       and v_challenge.code_hash = p_code_hash
       and v_target.discord_id = p_discord_id
       and v_challenge.consumed_at >= v_now - interval '10 minutes' then
      select public.observance_record_evidence(
        'discord:identity-link:LS05:' || p_discord_id || ':' || v_target.id::text,
        'LS05', 'discord',
        'discord:identity-link:LS05:' || p_discord_id || ':' || v_target.id::text,
        v_target.id,
        jsonb_build_object(
          'handler', 'identity_link', 'site_id', 'discord_link',
          'callback_verified', true, 'minecraft_proof_verified', true,
          'minecraft_name', v_target.name, 'recovered', v_challenge.recovered,
          'previous_player_id', v_challenge.previous_player_id
        )
      ) into v_inserted;
      return query select 'complete'::text, v_target.id, v_target.mc_uuid,
        v_target.name, p_discord_id, v_inserted, v_challenge.recovered;
      return;
    end if;
    return query select 'challenge'::text, null::uuid, null::text, null::text,
      null::text, false, false;
    return;
  end if;

  if v_challenge.expires_at <= v_now then
    return query select 'challenge'::text, null::uuid, null::text, null::text,
      null::text, false, false;
    return;
  end if;

  if v_challenge.code_hash <> p_code_hash then
    -- Five failures are counted per challenge. Further wrong guesses within 30 seconds remain a
    -- private no-op; an exact proof is never locked out by somebody else's guesses.
    update public.identity_link_challenges
       set failed_attempts = case
             when last_failed_at is null or last_failed_at < v_now - interval '30 seconds' then 1
             else least(5, failed_attempts + 1)
           end,
           last_failed_at = v_now
     where player_id = v_target.id
       and (failed_attempts < 5
         or last_failed_at is null
         or last_failed_at < v_now - interval '30 seconds');
    return query select 'challenge'::text, null::uuid, null::text, null::text,
      null::text, false, false;
    return;
  end if;

  -- Consume before identity mutation, in this same transaction. Any later exception rolls back the
  -- consumption, previous-row clear, target bind, and evidence receipt together.
  update public.identity_link_challenges
     set consumed_at = v_now,
         consumed_by_discord_id = p_discord_id
   where player_id = v_target.id and consumed_at is null;
  if not found then
    raise exception 'identity challenge changed while locked';
  end if;

  select p.*
    into v_previous
    from public.players p
   where p.discord_id = p_discord_id
   for update;
  v_had_previous := found;

  if v_had_previous and v_previous.id <> v_target.id then
    update public.players
       set discord_id = null
     where id = v_previous.id and discord_id = p_discord_id;
  end if;

  if v_target.discord_id is null then
    update public.players
       set discord_id = p_discord_id
     where id = v_target.id and discord_id is null
     returning * into v_target;
    if not found then
      raise exception 'identity claim changed while locked';
    end if;
  end if;

  select public.observance_record_evidence(
    'discord:identity-link:LS05:' || p_discord_id || ':' || v_target.id::text,
    'LS05', 'discord',
    'discord:identity-link:LS05:' || p_discord_id || ':' || v_target.id::text,
    v_target.id,
    jsonb_build_object(
      'handler', 'identity_link', 'site_id', 'discord_link',
      'callback_verified', true, 'minecraft_proof_verified', true,
      'minecraft_name', v_target.name,
      'recovered', v_had_previous and v_previous.id <> v_target.id,
      'previous_player_id', case
        when v_had_previous and v_previous.id <> v_target.id then v_previous.id
        else null
      end
    )
  ) into v_inserted;

  update public.identity_link_challenges
     set recovered = v_had_previous and v_previous.id <> v_target.id,
         previous_player_id = case
           when v_had_previous and v_previous.id <> v_target.id then v_previous.id
           else null
         end
   where player_id = v_target.id;

  return query select 'complete'::text, v_target.id, v_target.mc_uuid,
    v_target.name, p_discord_id, v_inserted,
    v_had_previous and v_previous.id <> v_target.id;
end;
$$;

revoke all on function public.observance_claim_identity_handoff(text,text,text,text)
  from public, anon, authenticated;
grant execute on function public.observance_claim_identity_handoff(text,text,text,text) to service_role;

commit;


