-- ============================================================
-- FILE: discord/supabase/migrations/0017_arg_events.sql
-- ============================================================

-- Open-ended, append-only campaign event ledger and cross-surface projection queue.
-- Event definitions describe story consequences, never a finite puzzle/mechanism taxonomy.
-- Correctness remains with each owning adapter; observation receipts are not consulted here.

begin;

create extension if not exists pgcrypto with schema extensions;

create table if not exists public.arg_event_definitions (
  event_key text primary key check (event_key ~ '^p(1[0-2]|[1-9])\.[a-z0-9_]+$'),
  phase_key text not null check (phase_key ~ '^P(1[0-2]|[1-9])$'),
  prerequisite_events text[] not null default '{}',
  source_surfaces text[] not null,
  projection_surfaces text[] not null,
  automation text not null default 'A1' check (automation in ('A0', 'A1')),
  active boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  check (cardinality(source_surfaces) > 0),
  check (cardinality(projection_surfaces) > 0),
  check (source_surfaces <@ array['minecraft','copperline','discord','dashboard','media','npc']::text[]),
  check (projection_surfaces <@ array['minecraft','copperline','discord','dashboard','media','npc']::text[])
);

create table if not exists public.arg_events (
  event_id uuid primary key default gen_random_uuid(),
  event_key text not null references public.arg_event_definitions(event_key) on delete restrict,
  idempotency_key text not null unique check (idempotency_key ~ '^[a-z0-9][a-z0-9:._/-]{7,159}$'),
  source text not null check (source in ('minecraft','copperline','discord','dashboard','media','npc')),
  actor_id text check (actor_id is null or actor_id ~ '^[A-Za-z0-9][A-Za-z0-9:._-]{0,127}$'),
  payload jsonb not null default '{}'::jsonb,
  payload_sha256 text not null check (payload_sha256 ~ '^[0-9a-f]{64}$'),
  occurred_at timestamptz not null default now(),
  check (octet_length(payload::text) <= 8192)
);

create index if not exists idx_arg_events_key_time
  on public.arg_events(event_key, occurred_at desc);

create table if not exists public.arg_event_projections (
  event_id uuid not null references public.arg_events(event_id) on delete cascade,
  surface text not null check (surface in ('minecraft','copperline','discord','dashboard','media','npc')),
  status text not null default 'queued' check (status in ('queued','applied','failed')),
  attempts integer not null default 0 check (attempts >= 0),
  last_error text,
  updated_at timestamptz not null default now(),
  primary key (event_id, surface)
);

create index if not exists idx_arg_event_projections_work
  on public.arg_event_projections(surface, status, updated_at)
  where status in ('queued', 'failed');

alter table public.arg_event_definitions enable row level security;
alter table public.arg_events enable row level security;
alter table public.arg_event_projections enable row level security;

revoke all on public.arg_event_definitions from public, anon, authenticated;
revoke all on public.arg_events from public, anon, authenticated;
revoke all on public.arg_event_projections from public, anon, authenticated;

grant select, insert, update on public.arg_event_definitions to service_role;
grant select, insert on public.arg_events to service_role;
grant select, insert, update on public.arg_event_projections to service_role;

insert into public.arg_event_definitions
  (event_key, phase_key, prerequisite_events, source_surfaces, projection_surfaces)
values
  ('p1.attachment_history_restored','P1','{}','{copperline}','{copperline,discord}'),
  ('p1.mkept_intent_authenticated','P1','{p1.attachment_history_restored}','{copperline,discord}','{copperline,discord}'),
  ('p2.artifact_authenticated','P2','{p1.mkept_intent_authenticated}','{copperline,discord}','{copperline,discord,dashboard}'),
  ('p2.live_runtime_handoff','P2','{p2.artifact_authenticated}','{minecraft,copperline}','{minecraft,copperline,discord}'),
  ('p3.resident_accounts_opened','P3','{p2.live_runtime_handoff}','{minecraft,npc}','{minecraft,npc,discord}'),
  ('p3.dispatch_authorized','P3','{p3.resident_accounts_opened}','{minecraft,discord}','{minecraft,copperline,discord,npc}'),
  ('p4.mouth_revision_restored','P4','{p3.dispatch_authorized}','{copperline}','{copperline,minecraft,discord}'),
  ('p4.copy_hypothesis_tested','P4','{p4.mouth_revision_restored}','{minecraft,discord}','{minecraft,copperline,discord,npc}'),
  ('p4.control_reversal_earned','P4','{p3.dispatch_authorized}','{minecraft}','{minecraft,copperline,discord,npc}'),
  ('p5.service_chronology_shared','P5','{p4.control_reversal_earned}','{minecraft,discord}','{minecraft,copperline,discord,npc}'),
  ('p5.civic_gallery_recurated','P5','{p5.service_chronology_shared}','{minecraft}','{minecraft,copperline,discord,npc}'),
  ('p6.professional_models_recovered','P6','{p5.civic_gallery_recurated}','{minecraft,discord}','{minecraft,copperline,discord,npc}'),
  ('p6.six_responsibilities_acknowledged','P6','{p6.professional_models_recovered}','{minecraft,discord}','{minecraft,copperline,discord,npc}'),
  ('p7.counterfeit_material_proven','P7','{p6.six_responsibilities_acknowledged}','{minecraft}','{minecraft,copperline,discord,npc}'),
  ('p7.supplier_history_restored','P7','{p7.counterfeit_material_proven}','{copperline}','{copperline,minecraft,discord}'),
  ('p7.nessa_publicly_cleared','P7','{p6.six_responsibilities_acknowledged}','{discord,npc}','{minecraft,copperline,discord,npc}'),
  ('p8.intervention_plan_accepted','P8','{p7.nessa_publicly_cleared}','{minecraft,discord}','{minecraft,copperline,discord,npc}'),
  ('p8.hold_systems_repaired','P8','{p8.intervention_plan_accepted}','{minecraft}','{minecraft,copperline,discord,npc}'),
  ('p9.company_biographies_restored','P9','{p8.hold_systems_repaired}','{minecraft,copperline,discord}','{minecraft,copperline,discord,media}'),
  ('p9.leak_window_proven','P9','{p9.company_biographies_restored}','{minecraft,discord,media}','{minecraft,copperline,discord,media,npc}'),
  ('p10.player_copy_proof','P10','{p9.leak_window_proven}','{minecraft}','{minecraft,copperline,discord,dashboard}'),
  ('p10.wren_confronted','P10','{p9.leak_window_proven}','{minecraft,discord,npc}','{minecraft,copperline,discord,npc}'),
  ('p10.wren_remembrance_committed','P10','{p10.wren_confronted}','{minecraft,discord}','{minecraft,copperline,discord,npc}'),
  ('p11.averyn_identified','P11','{p10.wren_remembrance_committed}','{minecraft,discord,media}','{minecraft,copperline,discord,npc}'),
  ('p11.averyn_restored_unbound','P11','{p11.averyn_identified}','{minecraft}','{minecraft,copperline,discord,npc}'),
  ('p12.release_configuration_ready','P12','{p11.averyn_restored_unbound}','{minecraft}','{minecraft,discord,dashboard}'),
  ('p12.name_treatment_committed','P12','{p12.release_configuration_ready}','{minecraft}','{minecraft,copperline,discord,dashboard,npc}'),
  ('p12.record_closed_averyn_released','P12','{p12.name_treatment_committed}','{minecraft}','{minecraft,copperline,discord,dashboard,npc}')
on conflict (event_key) do update set
  phase_key = excluded.phase_key,
  prerequisite_events = excluded.prerequisite_events,
  source_surfaces = excluded.source_surfaces,
  projection_surfaces = excluded.projection_surfaces,
  automation = excluded.automation,
  active = true,
  updated_at = now();

create or replace function public.observance_record_arg_event(
  p_event_key text,
  p_idempotency_key text,
  p_source text,
  p_actor_id text default null,
  p_payload jsonb default '{}'::jsonb
)
returns table (
  status text,
  created boolean,
  event_id uuid,
  missing_prerequisites text[]
)
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  definition public.arg_event_definitions%rowtype;
  prior public.arg_events%rowtype;
  missing text[];
  canonical_hash text;
  inserted_id uuid;
  projection text;
begin
  if p_idempotency_key !~ '^[a-z0-9][a-z0-9:._/-]{7,159}$'
     or p_actor_id is not null and p_actor_id !~ '^[A-Za-z0-9][A-Za-z0-9:._-]{0,127}$'
     or octet_length(coalesce(p_payload, '{}'::jsonb)::text) > 8192 then
    raise exception 'invalid ARG event input';
  end if;

  select * into definition
    from public.arg_event_definitions
    where event_key = p_event_key and active = true
    for share;
  if not found then raise exception 'unknown or inactive ARG event'; end if;
  if not p_source = any(definition.source_surfaces) then
    raise exception 'source surface cannot record this ARG event';
  end if;

  canonical_hash := encode(extensions.digest(convert_to(coalesce(p_payload, '{}'::jsonb)::text, 'UTF8'), 'sha256'), 'hex');
  select * into prior from public.arg_events where idempotency_key = p_idempotency_key;
  if found then
    if prior.event_key = p_event_key and prior.source = p_source
       and prior.actor_id is not distinct from p_actor_id and prior.payload_sha256 = canonical_hash then
      return query select 'committed'::text, false, prior.event_id, '{}'::text[];
    else
      return query select 'collision'::text, false, prior.event_id, '{}'::text[];
    end if;
    return;
  end if;

  select coalesce(array_agg(required order by required), '{}'::text[]) into missing
  from unnest(definition.prerequisite_events) as required
  where not exists (select 1 from public.arg_events e where e.event_key = required);
  if cardinality(missing) > 0 then
    return query select 'blocked'::text, false, null::uuid, missing;
    return;
  end if;

  insert into public.arg_events(event_key, idempotency_key, source, actor_id, payload, payload_sha256)
  values (p_event_key, p_idempotency_key, p_source, p_actor_id, coalesce(p_payload, '{}'::jsonb), canonical_hash)
  returning arg_events.event_id into inserted_id;

  foreach projection in array definition.projection_surfaces loop
    insert into public.arg_event_projections(event_id, surface, status, attempts)
    values (inserted_id, projection, case when projection = p_source then 'applied' else 'queued' end,
      case when projection = p_source then 1 else 0 end);
  end loop;

  update public.arc_state
    set flags = coalesce(flags, '{}'::jsonb) || jsonb_build_object(p_event_key, true),
        updated_at = now()
    where id = 1;

  return query select 'committed'::text, true, inserted_id, '{}'::text[];
end;
$$;

revoke all on function public.observance_record_arg_event(text,text,text,text,jsonb)
  from public, anon, authenticated;
grant execute on function public.observance_record_arg_event(text,text,text,text,jsonb)
  to service_role;

commit;


-- ============================================================
-- FILE: dashboard/supabase/migrations/0004_v_record.sql
-- ============================================================

-- The Observance — 0004_v_record.sql
-- The public Record's ONE read surface (P1-W1 / BUILD-MANIFEST §7 / INTEGRATION-V2 §A13).
--
-- WHY THIS FILE. `dashboard/src/app/record/[slug]/page.tsx` reads a view named `v_record`
-- (page.tsx:95, select "movement, stones_read, accepted"), but no migration ever created it.
-- Every read hit the page's catch and the archive degraded to the sealed baseline — permanently
-- frozen, never un-redacting with progress. This migration authors that view.
--
-- SECURITY MODEL — IDENTICAL to the three views in 0001_init.sql (v_health / v_heatmap /
-- v_compliance_counts). It is a SECURITY DEFINER view (`security_invoker = false`, the Postgres
-- default made explicit): it runs with the view OWNER's privileges (the migration role, which owns
-- the base tables), so anon can read the neutral projection WITHOUT any table grant and WITHOUT any
-- anon RLS policy on the spoiler tables. anon never touches raw rows — only the three COARSE columns
-- below. Deny-by-default holds: the base tables (arc_state, solves, puzzles) have RLS enabled, no
-- anon policy, and revoked anon grants (0003_lockdown / 0004_oracle); this view is the ONLY anon path.
--
-- SPOILER-SAFETY (the contract record-projection.ts already clamps to). The view exposes EXACTLY:
--   * movement    int  — the coarse season (1..5), from arc_state.current_act. A season pointer, not
--                        a puzzle answer. Clamped to the SEASONS band the projection knows.
--   * stones_read int  — how many of the SIX keeper-stones have been solved (0..6), a bare COUNT over
--                        solves. No puzzle_key, no answer, no label, no player — just the tally, the
--                        same shape v_compliance_counts uses to expose counts over a spoiler table.
--   * accepted   bool  — whether the Accepting has resolved (arc_state.flags carries record_received
--                        or bowed_as_one). The single arc-end signal the Record may know. A boolean.
-- It exposes ZERO unsolved answers, ZERO story/custom labels, ZERO player names, and no per-flag
-- structure (only the one closed-flag boolean). Un-redaction is progressive: stones_read rises only
-- as stones are actually solved, so entries go legible in lockstep with real progress, never ahead.
--
-- Single row (arc_state is a single row, id=1). Additive + idempotent (create or replace) — safe to
-- re-run. Apply as the migration/service role AFTER the discord lineage's 0004_oracle.sql (which
-- creates public.solves) and 0006_requires_flags.sql have landed on the live project. Depends only
-- on tables that exist by then; touches nothing else.

begin;

drop view if exists public.v_record;

-- v_record: the coarse, spoiler-free public archive signal. Reads the spoiler tables as the view
-- owner and projects only the three blunt public facts the sealed Record is allowed to show.
create or replace view public.v_record
with (security_invoker = false) as
select
  -- coarse season (1..5): the author-advanced act pointer. Clamped to the projection's band so a
  -- stray value can never over-reveal (record-projection.ts re-clamps 0..5 defensively as well).
  least(greatest(coalesce((select current_act from public.arc_state where id = 1), 1), 1), 5)::int
    as movement,

  -- how many of the six keeper evidence clusters have their first keeper read solved. A bare count
  -- over solves, filtered to the current six canonical keeper keys — no key, answer, label, or
  -- player leaves the view. Sella's retired Atbash row is intentionally not counted; her live read is
  -- the water/reflection bearing.
  (select count(distinct s.puzzle_key)
     from public.solves s
    where s.puzzle_key in (
      'stone-vaun', 'stone-mara', 'sella-reflection-bearing',
      'stone-orin', 'stone-brann', 'stone-iss-wall'
    ))::int
    as stones_read,

  -- the keeping has closed: the Accepting resolved. The only arc-end signal the Record may surface,
  -- reduced to a single boolean (never the flags blob itself).
  coalesce(
    (select (flags ? 'record_received') or (flags ? 'bowed_as_one')
       from public.arc_state where id = 1),
    false)
    as accepted;

comment on view public.v_record is
  'Public, anon-readable coarse Record signal (P1-W1). SECURITY DEFINER; exposes ONLY '
  '{movement, stones_read, accepted} — a season pointer, a keeper-stone COUNT, and a closed '
  'boolean. No answers, labels, player names, or flag structure. Consumed by record/[slug]/page.tsx '
  'via record-projection.ts, which clamps every field. Un-redacts in lockstep with real solves.';

-- The ONLY grant: anon (and authenticated) may SELECT the neutral view. Mirrors 0001_init.sql's
-- grants for v_health / v_heatmap / v_compliance_counts. anon still has no base-table grant/policy.
grant select on public.v_record to anon, authenticated;

commit;


-- ============================================================
-- FILE: dashboard/supabase/migrations/0005_reconcile_tracker_views.sql
-- ============================================================

-- The Observance (dashboard) — 0005_reconcile_tracker_views.sql
-- ---------------------------------------------------------------------------
-- Fixes the LAST leg of the plugin<->dashboard drift for dossiers + customs so
-- the Author page stops rendering blank rows.
--
-- BACKGROUND. discord/supabase/schema-repair.sql made the two spoiler tables
-- ADDITIVE-compatible with the Java plugin: the plugin now upserts FLAT,
-- mc_uuid-keyed rows with RENAMED/RETYPED columns and a NULL player_id:
--   dossiers          : solo_mining_seconds (bigint), hoarded_score (double),
--                       distance_from_group (double), extra (text), name, mc_uuid
--                       — but NOT solo_ratio / group_distance / hoard_summary,
--                         and player_id is NULL for every plugin-written row.
--   custom_compliance : honored_count, violated_count, last_event_at, name,
--                       mc_uuid — but NOT status / violation_count / last_observed,
--                         and player_id is NULL for every plugin-written row.
--
-- The dashboard (author/page.tsx + Dossiers.tsx) still reads the ORIGINAL
-- 0001_init shape declared in database.types.ts — solo_ratio / group_distance /
-- hoard_summary / chat_sentiment / updated_at, and status / violation_count /
-- last_observed — AND joins both tables to players BY player_id. Two things
-- drifted at once: (1) column names+types, and (2) the join KEY (mc_uuid vs
-- player_id). A pure read-column rename cannot fix (2): even with correct names
-- the player_id join would still miss NULL-player_id plugin rows and stay blank.
--
-- FIX (smallest-safe, view-based). Add two reconciling SECURITY DEFINER views
-- that JOIN plugin rows back to players via players.mc_uuid to SYNTHESIZE
-- player_id, and alias/coerce the flat columns into EXACTLY the shape
-- database.types.ts already declares. Only two dashboard `from()` table names
-- change (dossiers -> v_dossiers, custom_compliance -> v_custom_compliance);
-- the TS types, the player_id joins, and Dossiers.tsx stay untouched. Old
-- player_id-keyed rows (if any) still resolve — the join is on mc_uuid, which
-- both old and new rows carry.
--
-- SECURITY. These views are SPOILER-RICH (player names, custom_key labels,
-- per-player signals) — they are NOT for anon. Mirroring the deny-by-default
-- posture 0003_lockdown established: the base tables have RLS on, no anon/
-- authenticated policy, and revoked grants; the dashboard reads them ONLY via
-- the server-side service_role client behind isAdmin() (service_role bypasses
-- RLS and grants). So these views get NO grant to anon or authenticated — we
-- REVOKE from both explicitly. Only service_role (the dashboard's admin client)
-- reads them. This does NOT weaken RLS and never exposes the service key.
--
-- Additive + idempotent (create or replace view). ORDER-INDEPENDENT: the shim
-- below adds the flat plugin columns these views alias, so this migration may be
-- applied before OR after discord/supabase/schema-repair.sql (both idempotent).
-- ---------------------------------------------------------------------------

begin;

-- ---------------------------------------------------------------------------
-- COMPATIBILITY SHIM (order-independence). These views alias the flat plugin
-- columns that discord/supabase/schema-repair.sql adds to dossiers /
-- custom_compliance. Guarantee those columns exist FIRST so this migration can be
-- hand-applied in ANY order relative to schema-repair (a stray order previously
-- errored: "column d.mc_uuid does not exist"). Idempotent + type-matched to
-- schema-repair, so whichever lands first wins and the other no-ops. Column DATA
-- is still populated only by the plugin's upserts; this just ensures the view can
-- be CREATED regardless of apply order.
alter table public.dossiers
  add column if not exists mc_uuid             text,
  add column if not exists solo_mining_seconds bigint,
  add column if not exists hoarded_score       double precision,
  add column if not exists distance_from_group double precision,
  add column if not exists extra               text;

alter table public.custom_compliance
  add column if not exists mc_uuid        text,
  add column if not exists violated_count int default 0,
  add column if not exists last_event_at  timestamptz;
-- ---------------------------------------------------------------------------

-- v_dossiers — plugin FLAT dossier rows reshaped into the dashboard's declared
-- Tables<'dossiers'> Row. Joins to players by mc_uuid to synthesize player_id.
--   * solo_ratio     <- solo_mining_seconds (bigint -> numeric via ::numeric)
--   * group_distance <- distance_from_group (double)
--   * hoard_summary  <- extra (the plugin's free-form JSON string) when present,
--                       else the numeric hoarded_score rendered as text.
--   * deaths / blocks_mined / chat_sentiment / updated_at pass through the base
--     columns (chat_sentiment has no plugin source yet -> null, which the type
--     already allows).
drop view if exists public.v_dossiers;

create or replace view public.v_dossiers
with (security_invoker = false) as
select
  p.id                                        as player_id,
  coalesce(d.solo_mining_seconds::numeric, d.solo_ratio, 0) as solo_ratio,
  coalesce(d.deaths, 0)                        as deaths,
  coalesce(
    nullif(d.extra, ''),
    case when d.hoarded_score is not null then d.hoarded_score::text else null end,
    d.hoard_summary
  )                                            as hoard_summary,
  coalesce(d.distance_from_group, d.group_distance) as group_distance,
  d.chat_sentiment                             as chat_sentiment,
  coalesce(d.blocks_mined, 0)                  as blocks_mined,
  d.updated_at                                 as updated_at
from public.dossiers d
join public.players p on p.mc_uuid = d.mc_uuid;

comment on view public.v_dossiers is
  'Reconciling view (0005). Reshapes the plugin''s flat mc_uuid-keyed dossiers into the '
  'dashboard''s declared Tables<dossiers> Row (player_id synthesized via players.mc_uuid). '
  'SPOILER-RICH (names, per-player signals): SECURITY DEFINER, read ONLY by the service_role '
  'admin client — NO anon/authenticated grant.';

-- v_custom_compliance — plugin FLAT custom rows reshaped into the dashboard's
-- declared Tables<'custom_compliance'> Row. Joins to players by mc_uuid.
--   * violation_count <- violated_count
--   * last_observed   <- last_event_at
--   * status          <- DERIVED (no plugin source): the same rung semantics the
--                        author page/customs.ts use — LEFT_AT (5) standing
--                        violations = 'violating', any standing violation =
--                        'warned', else 'keeping'. Matches Dossiers.tsx's
--                        COMPLIANCE_STYLES keys (keeping/warned/violating).
--   * id / custom_key pass through the base columns.
drop view if exists public.v_custom_compliance;

create or replace view public.v_custom_compliance
with (security_invoker = false) as
select
  c.id                                         as id,
  p.id                                         as player_id,
  c.custom_key                                 as custom_key,
  c.last_event_at                              as last_observed,
  coalesce(c.violated_count, c.violation_count, 0) as violation_count,
  case
    when coalesce(c.violated_count, c.violation_count, 0) >= 5 then 'violating'
    when coalesce(c.violated_count, c.violation_count, 0) > 0  then 'warned'
    else 'keeping'
  end                                          as status
from public.custom_compliance c
join public.players p on p.mc_uuid = c.mc_uuid;

comment on view public.v_custom_compliance is
  'Reconciling view (0005). Reshapes the plugin''s flat mc_uuid-keyed custom_compliance into '
  'the dashboard''s declared Tables<custom_compliance> Row (player_id synthesized via '
  'players.mc_uuid; status derived from violated_count using the LEFT_AT=5 rung). SPOILER-RICH '
  '(names, custom_key labels): SECURITY DEFINER, read ONLY by the service_role admin client — '
  'NO anon/authenticated grant.';

-- Deny-by-default (0003_lockdown posture): these spoiler-rich views are read
-- ONLY via the service_role client. Explicitly revoke from anon + authenticated
-- so a stray default grant can never expose player names / custom labels.
revoke all on public.v_dossiers          from anon, authenticated;
revoke all on public.v_custom_compliance from anon, authenticated;

commit;


-- ============================================================
-- FILE: dashboard/supabase/migrations/0006_v_record_theories.sql
-- ============================================================

-- The Observance — 0006_v_record_theories.sql
-- Reshape S-D dovetail: the Record RECEIVES a keeper's fate by THEORY, not by lookup.
--
-- WHY. Wave S-D added the "build a theory" mechanic: the showrunner sets a derived `<keeper>_theory`
-- flag in arc_state.flags when a coherent CLUSTER of that keeper's evidence is solved (theory.ts /
-- theory.run.ts). The public Record should reflect ASSEMBLED THEORIES — a keeper's fate un-redacts when
-- the group has put the keeper together, not when they've cracked one cipher (reward the theory, not the
-- lookup). This migration exposes those six coarse booleans to the Record's one anon read surface.
--
-- SECURITY MODEL — unchanged from 0004_v_record.sql. Still a SECURITY DEFINER view (security_invoker =
-- false); anon reads only the neutral projection, never a base row. The new column is the SAME coarse
-- granularity as stones_read: it says only WHICH of the six named keeper-theories are coherent — a group
-- progress signal. It exposes ZERO answers, ZERO puzzle_keys, ZERO player names, ZERO other flag
-- structure. The keeper ids (vaun/mara/…) are the DEAD keepers' canonical names, already public in the
-- in-world record; never a living player. Un-redaction stays in lockstep with real progress (a theory
-- appears only once its cluster is actually solved).
--
-- Additive + idempotent (create or replace, adding one trailing column — Postgres-legal). Re-grants anon
-- SELECT (preserved across replace, re-granted defensively). Apply AFTER 0004_v_record.sql. Depends only
-- on arc_state (jsonb flags) + solves, which exist by then.

begin;

drop view if exists public.v_record;

create or replace view public.v_record
with (security_invoker = false) as
select
  -- coarse season (1..5): the author-advanced act pointer (unchanged from 0004).
  least(greatest(coalesce((select current_act from public.arc_state where id = 1), 1), 1), 5)::int
    as movement,

  -- how many of the six keeper evidence clusters have their first keeper read solved — the bare count
  -- (unchanged from 0004 except Sella's retired Atbash row is not counted). Retained as the progressive
  -- fallback the projection uses before any theory has locked.
  (select count(distinct s.puzzle_key)
     from public.solves s
    where s.puzzle_key in (
      'stone-vaun', 'stone-mara', 'sella-reflection-bearing',
      'stone-orin', 'stone-brann', 'stone-iss-wall'
    ))::int
    as stones_read,

  -- the keeping has closed: the Accepting resolved (unchanged from 0004).
  coalesce(
    (select (flags ? 'record_received') or (flags ? 'bowed_as_one')
       from public.arc_state where id = 1),
    false)
    as accepted,

  -- NEW (S-D): which of the six keeper theories are coherent, in fall-order. A text[] of keeper ids
  -- whose `<keeper>_theory` flag is truthy in arc_state.flags. Same coarse granularity as stones_read;
  -- the projection maps each to its fixed archive entry so the fate un-redacts on the assembled theory.
  coalesce(
    (select array_agg(t.k order by t.ord)
       from (values ('vaun', 1), ('mara', 2), ('sella', 3),
                    ('orin', 4), ('brann', 5), ('iss', 6)) as t(k, ord)
       cross join public.arc_state a
      where a.id = 1
        and coalesce((a.flags ->> (t.k || '_theory'))::boolean, false)),
    array[]::text[])
    as theories;

comment on view public.v_record is
  'Public, anon-readable coarse Record signal (P1-W1 + S-D). SECURITY DEFINER; exposes ONLY '
  '{movement, stones_read, accepted, theories} — a season pointer, a keeper-stone COUNT, a closed '
  'boolean, and the set of coherent keeper-theory ids (dead-keeper names, group progress). No answers, '
  'labels, player names, or wider flag structure. Consumed by record/[slug]/page.tsx via '
  'record-projection.ts, which clamps every field. Un-redacts in lockstep with real solves/theories.';

grant select on public.v_record to anon, authenticated;

commit;


-- ============================================================
-- FILE: dashboard/supabase/migrations/0007_v_archive.sql
-- ============================================================

-- The Observance — 0007_v_archive.sql
-- The Recovery Archive's public read surface (W3a — the field/offshoots wave).
--
-- WHY THIS FILE. The reshape authored 42 place-anchored thread_cards (the reconstruction
-- field: who / place / happened / surface / human) — verbatim recovered material, each
-- clustered under a thread and wired into a citation web. They were seeded + voice-covered
-- + self-tested, but NOTHING ever surfaced them to players: thread_cards was written and
-- never read. The Record showed only its six coarse stone-lines (v_record). This migration
-- gives the archive its public reading surface, so the "dig, connect the dots, watch the
-- threads rhyme" layer the cards were authored for becomes a thing players can actually do.
--
-- SECURITY MODEL — IDENTICAL to v_record (0004) and the 0001_init views. v_archive is a
-- SECURITY DEFINER view (security_invoker = false): it runs with the OWNER's privileges, so
-- anon reads the neutral projection with NO base-table grant and NO anon RLS policy. anon
-- never touches a raw row — only the reveal-gated columns below. Deny-by-default holds
-- (thread_cards / thread_card_bodies / solves / arc_state have RLS on, no anon policy,
-- revoked anon grants); this view is the ONLY anon path to a card.
--
-- REVEAL DISCIPLINE (the whole point — a body NEVER leaves the view ahead of progress). The
-- WHERE clause below is the reveal rule, computed here in SQL from public.solves +
-- arc_state.flags (the same shape v_record counts). A card row is emitted iff:
--   * revealed_by_solve is a solved puzzle_key, OR
--   * alt_text_condition = 'reopened:<key>' and <key> is solved (the re-surface trigger), OR
--   * alt_text_condition = 'companion:revealed' and arc_state.flags carries companion_revealed.
-- A card with no solve-gate and no recognised condition (the few pure 'found-on-descent'
-- atmosphere cards) is WITHHELD until the seed gives it an explicit gate — the Record's own
-- ethos (withhold, never over-reveal). No unearned body reaches anon; the archive un-redacts
-- in lockstep with real solves, exactly like the six stone-lines already do.
--
-- INV-1 (the voice rule) STAYS INTACT. The authored English lives in ONE place —
-- discord/src/voice.archive.ts (the archive/npcLines maps; canon.ts GUARD-9 pins every
-- body_voice_key to an entry there). thread_card_bodies is that text's DB REALIZATION, written
-- ONLY by the showrunner's archive materializer (archive.run.ts) as service_role — never
-- hand-authored here, never composed in the dashboard. The dashboard is a dumb renderer of the
-- neutral view, the same way it renders v_record.
--
-- Additive + idempotent (create table if not exists / create or replace view). Apply as the
-- migration/service role AFTER the discord lineage's thread_cards (0005_threads.sql) and
-- solves (0004_oracle.sql) exist on the live project. Touches nothing else.

begin;

-- 1. thread_card_bodies — the resolved-body store. One row per card, body = the recovered
--    text resolved from voice.archive.ts by the showrunner materializer. RLS on, NO anon
--    grant: only the service role writes it, only v_archive reads it (as the view owner).
--    Holding the bodies here (not in thread_cards) keeps the authored source single (INV-1):
--    the materializer is the sole writer, and it reads voice.archive.ts, never the reverse.
create table if not exists public.thread_card_bodies (
  card_key   text primary key references public.thread_cards(card_key) on delete cascade,
  body       text not null,
  updated_at timestamptz not null default now()
);

alter table public.thread_card_bodies enable row level security;
-- (no policy, no grant: deny-by-default. service_role bypasses RLS to upsert; v_archive
--  reads as owner. anon has neither a policy nor a grant, so it can never read this table.)
revoke all on public.thread_card_bodies from anon, authenticated;

-- 2. v_archive — the neutral, anon-readable reconstruction field. One row per REVEALED card,
--    carrying only the reconstruction columns the Record is allowed to show: the thread it
--    clusters under (+ the thread's player-facing label/colour, from public.threads), the card
--    title + recovered body, its kind (rumor/explore/verified/contradicted), the citation web
--    (references_card_key — kebab slugs, no bodies), and the sort orders. No answer, no player,
--    no custom label, no sealed flag. The reveal gate is the WHERE clause (see header).
drop view if exists public.v_archive;

create or replace view public.v_archive
with (security_invoker = false) as
select
  c.card_key,
  c.thread_key,
  t.label               as thread_label,
  t.color               as thread_color,
  t.sort_order          as thread_sort,
  c.title,
  b.body,
  c.card_kind,
  c.references_card_key,
  c.sort_order          as card_sort
from public.thread_cards c
join public.threads t             on t.thread_key = c.thread_key
join public.thread_card_bodies b  on b.card_key  = c.card_key
where
  -- solve-gated: the card's own puzzle has been read (the common case).
  (c.revealed_by_solve is not null
     and c.revealed_by_solve in (select s.puzzle_key from public.solves s))
  -- re-surface trigger (e.g. the seventh marker reopened by the catch): alt gate names a solve.
  or (c.alt_text_condition like 'reopened:%'
     and substring(c.alt_text_condition from 'reopened:(.*)')
           in (select s.puzzle_key from public.solves s))
  -- the companion reveal event (Wren): a single flag, never the flags blob itself.
  or (c.alt_text_condition = 'companion:revealed'
     and coalesce((select (flags ? 'companion_revealed') from public.arc_state where id = 1), false));

comment on view public.v_archive is
  'Public, anon-readable Recovery Archive (W3a). SECURITY DEFINER; emits ONE row per REVEALED '
  'thread_card — {thread, label, colour, title, body, kind, references, sort}. Reveal is gated in '
  'SQL from solves + arc_state.flags (solve / reopened:<key> / companion:revealed); an unrevealed '
  'body never leaves the view. Bodies are materialised from voice.archive.ts by the showrunner '
  '(INV-1). Consumed by the Record archive reading-room via archive-projection.ts.';

-- The ONLY grant: anon (and authenticated) may SELECT the neutral view. Mirrors v_record.
grant select on public.v_archive to anon, authenticated;

commit;


-- ============================================================
-- FILE: dashboard/supabase/migrations/0008_v_archive_flag_gate.sql
-- ============================================================

-- The Observance — 0008_v_archive_flag_gate.sql
-- Generalize the Recovery Archive reveal rule (v_archive, 0007) with a `flag:<name>` gate.
--
-- WHY. 0007 reveals a card by SOLVE (revealed_by_solve), by a re-surface trigger (alt_text_condition
-- 'reopened:<key>'), or by the one companion event ('companion:revealed'). But several authored cards are
-- EVENT-revealed, not solve-revealed: the group gather-event cards (verified when a gather flag flips) and
-- the Nether/End deep-lane cards (revealed when the lane's flag is set on arrival). They carry no puzzle
-- gate, so 0007 withholds them forever. This adds ONE general branch — `alt_text_condition = 'flag:<name>'`
-- reveals the card iff `arc_state.flags ? '<name>'` — so any card can be gated on any set-once arc flag.
-- ('companion:revealed' is kept as its own branch for back-compat with the seed that already uses it; it
-- is exactly the 'flag:companion_revealed' case.)
--
-- SECURITY unchanged: still a SECURITY DEFINER view exposing only revealed rows; anon reads the neutral
-- projection with no base-table grant. Reveal stays gated in SQL over solves + arc_state.flags; an
-- unrevealed body never leaves the view. Additive + idempotent (create or replace). Apply after 0007.

begin;

drop view if exists public.v_archive;

create or replace view public.v_archive
with (security_invoker = false) as
select
  c.card_key,
  c.thread_key,
  t.label               as thread_label,
  t.color               as thread_color,
  t.sort_order          as thread_sort,
  c.title,
  b.body,
  c.card_kind,
  c.references_card_key,
  c.sort_order          as card_sort
from public.thread_cards c
join public.threads t             on t.thread_key = c.thread_key
join public.thread_card_bodies b  on b.card_key  = c.card_key
where
  -- solve-gated: the card's own puzzle has been read (the common case).
  (c.revealed_by_solve is not null
     and c.revealed_by_solve in (select s.puzzle_key from public.solves s))
  -- re-surface trigger (e.g. the seventh marker reopened by the catch): alt gate names a solve.
  or (c.alt_text_condition like 'reopened:%'
     and substring(c.alt_text_condition from 'reopened:(.*)')
           in (select s.puzzle_key from public.solves s))
  -- the companion reveal event (Wren) — kept as-is for the seed that names it.
  or (c.alt_text_condition = 'companion:revealed'
     and coalesce((select (flags ? 'companion_revealed') from public.arc_state where id = 1), false))
  -- GENERAL flag gate (W3): 'flag:<name>' reveals iff arc_state.flags carries <name> (gather-event
  -- cards, Nether/End lane cards, any future event-revealed card). Never the flags blob itself.
  or (c.alt_text_condition like 'flag:%'
     and coalesce(
           (select (flags ? substring(c.alt_text_condition from 'flag:(.*)')) from public.arc_state where id = 1),
           false));

comment on view public.v_archive is
  'Public, anon-readable Recovery Archive (W3a + 0008). SECURITY DEFINER; one row per REVEALED thread_card. '
  'Reveal gated in SQL: revealed_by_solve solved · alt_text_condition reopened:<key> solved · '
  'companion:revealed flag · flag:<name> arc flag set. An unrevealed body never leaves the view.';

grant select on public.v_archive to anon, authenticated;

commit;


-- ============================================================
-- FILE: dashboard/supabase/migrations/0009_beat_queue_failed_status.sql
-- ============================================================

-- 0009_beat_queue_failed_status.sql - allow plugin runtime beat statuses.
--
-- The plugin claims an approved beat by moving it to status='firing' before world mutation, then writes
-- a terminal status ('fired', 'skipped', or 'failed') afterward. The beat_queue table is born in the
-- dashboard lineage, while the plugin status contract is maintained in the Discord lineage, so keep this
-- dashboard-side repair in sync.

alter table if exists public.beat_queue
  drop constraint if exists beat_queue_status_check;

alter table if exists public.beat_queue
  add constraint beat_queue_status_check
  check (status in ('pending', 'approved', 'firing', 'skipped', 'fired', 'failed'));


-- ============================================================
-- FILE: dashboard/supabase/migrations/0010_v5_public_record.sql
-- ============================================================

-- The Observance V5 public projections.
-- Every view is intentionally narrower than the service-role tables: no accepted answers, no hidden
-- prerequisites, no player identities, and no future node titles. Public rows appear only when their
-- case is unlocked or their evidence is already earned.

begin;

drop view if exists public.v_record;
create view public.v_record
with (security_invoker = false) as
with state as (
  select current_act, phase_key, coalesce(flags, '{}'::jsonb) flags
    from public.arc_state where id = 1
), totals as (
  select count(*)::int total_nodes
    from public.investigation_nodes where active and required
), done as (
  select count(*)::int nodes_completed
    from public.investigation_nodes n cross join state s
   where n.active and n.required
     and coalesce((s.flags ->> n.completion_flag)::boolean, false)
), cases as (
  select count(*)::int cases_completed
    from public.investigations i cross join state s
   where i.active and i.required
     and coalesce((s.flags ->> i.completion_flag)::boolean, false)
), current_case as (
  select
    i.case_key,
    case
      when coalesce((s.flags ->> i.completion_flag)::boolean, false) then i.title
      else 'Docket ' || i.case_key
    end as public_title
    from public.investigations i cross join state s
   where i.active and i.required
     and (i.ordinal = 1 or coalesce((s.flags ->> i.unlock_flag)::boolean, false))
   order by i.ordinal desc limit 1
)
select
  s.current_act as movement,
  s.phase_key,
  c.case_key as current_case_key,
  c.public_title as current_case_title,
  cases.cases_completed,
  done.nodes_completed,
  totals.total_nodes,
  coalesce((s.flags ->> 'v5_case_c10_complete')::boolean, false) as closed,
  case when coalesce((s.flags ->> 'v5_case_c10_complete')::boolean, false)
       then s.flags ->> 'v5_ending_branch' end as ending_branch,
  case when coalesce((s.flags ->> 'v5_case_c10_complete')::boolean, false)
       then s.flags ->> 'v5_name_treatment' end as name_treatment,
  case when coalesce((s.flags ->> 'v5_case_c10_complete')::boolean, false)
       then s.flags ->> 'v5_wren_outcome' end as wren_outcome
from state s cross join totals cross join done cross join cases
left join current_case c on true;

comment on view public.v_record is
  'V5 spoiler-safe Record muster: coarse act/phase, current unlocked case, mandatory case/node counts, and final choices only after closure.';
grant select on public.v_record to anon, authenticated;

create or replace view public.v_case_progress
with (security_invoker = false) as
select
  i.case_key,
  i.ordinal,
  case
    when coalesce((a.flags ->> i.completion_flag)::boolean, false) then i.title
    else 'Docket ' || i.case_key
  end as title,
  case
    when coalesce((a.flags ->> i.completion_flag)::boolean, false) then i.summary
    else 'Docket open. Recover and file evidence at its named surface.'
  end as summary,
  count(n.node_key)::int as total_nodes,
  count(n.node_key) filter (
    where coalesce((a.flags ->> n.completion_flag)::boolean, false)
  )::int as completed_nodes,
  coalesce((a.flags ->> i.completion_flag)::boolean, false) as complete
from public.investigations i
cross join public.arc_state a
join public.investigation_nodes n on n.case_key = i.case_key and n.active and n.required
where a.id = 1 and i.active and i.required
  and (i.ordinal = 1 or coalesce((a.flags ->> i.unlock_flag)::boolean, false))
group by i.case_key,i.ordinal,i.title,i.summary,i.completion_flag,a.flags
order by i.ordinal;

comment on view public.v_case_progress is
  'Only unlocked mandatory cases, with coarse completion counts. Incomplete cases expose a generic docket label; canonical titles and summaries appear only after completion.';
grant select on public.v_case_progress to anon, authenticated;

drop view if exists public.v_archive;
create view public.v_archive
with (security_invoker = false) as
select
  n.node_key,
  n.case_key,
  i.ordinal as case_ordinal,
  i.title as case_title,
  n.ordinal as node_ordinal,
  n.title,
  n.modality,
  n.reward,
  coalesce(
    (select min(r.received_at) from public.evidence_receipts r where r.node_key = n.node_key),
    a.updated_at
  ) as recovered_at
from public.investigation_nodes n
join public.investigations i on i.case_key = n.case_key
cross join public.arc_state a
where a.id = 1 and n.active and n.required and i.active and i.required
  and coalesce((a.flags ->> n.completion_flag)::boolean, false)
order by i.ordinal,n.ordinal;

comment on view public.v_archive is
  'V5 recovered evidence only. A node title and payoff leave the database only after its durable completion flag is true.';
grant select on public.v_archive to anon, authenticated;

create or replace view public.v_required_media_delivery
with (security_invoker = false) as
select
  m.media_key,
  m.case_key,
  m.node_key,
  m.media_kind,
  m.title,
  m.delivery_url,
  m.filename,
  m.delivery_state
from public.required_media m
cross join public.arc_state a
where a.id = 1 and m.active
  and not exists (
    select 1 from unnest(m.prerequisite_flags) as required_flag
     where not coalesce((a.flags ->> required_flag)::boolean, false)
  );

comment on view public.v_required_media_delivery is
  'Prerequisite-gated delivery routes for required V5 media. Expected payloads and checksums remain service-role only.';
grant select on public.v_required_media_delivery to anon, authenticated;

commit;


-- ============================================================
-- FILE: discord/supabase/seeds/puzzles_seed.sql
-- ============================================================

-- The Observance — PUZZLES SEED (realizes design/clue-web.md in the 0004 schema)
-- discord/supabase/seeds/puzzles_seed.sql
--
-- One INSERT per web node (design/clue-web.md §3). Every accepted_answers entry is
-- ALREADY NORMALIZED per ORACLE.md §2 (NFKC → lower → [^a-z0-9 ]→single space →
-- collapse ws → trim). The resolver normalizes player input the same way and tests
-- whole-string set-membership, so a raw "Bow, at!" or "-1280, 64" must equal one of
-- these stored strings AFTER normalization. Coordinate answers therefore appear in
-- BOTH unsigned and direction-word forms (the minus sign is dropped by step 3, so a
-- signed coord like "-1280 64" normalizes to "1280 64" — we store "1280 64" and also
-- the spoken bearing the carving gives).
--
-- Outcome wiring (ORACLE.md §3):
--   next_clue  → voice_key + next_puzzle_key (the door onward)
--   lore       → voice_key (+ voice_args.fragment) ONLY — a told secret, no door
--   dead_end   → voice_key ONLY — TRUE but opens nothing (no next, no beat)
--   side_quest → voice_key + next_puzzle_key (off-spine branch)
--   main_beat  → voice_key + 'unlock' beat {type,site_id,step,step_payload} + set_flags
--
-- Beats are enqueued status='approved' by the Oracle path (resolve.ts → the player
-- EARNED it; ORACLE.md §4). The "{solver}" mc_uuid placeholder is resolved to the
-- solving player's real uuid at enqueue time. beat.payload is real jsonb (not a
-- quoted string) — see ORACLE.md §4 "Plugin payload typing — RESOLVED".
--
-- IDEMPOTENT: ON CONFLICT (puzzle_key) DO UPDATE re-applies every authored field, so
-- re-running this file is safe and is the canonical way to edit a node. We touch the
-- 5 author-owned columns + active; created_at is left to the existing row.
--
-- Run AFTER 0004_oracle.sql, as service_role (RLS bypass — these are spoiler tables).

begin;

insert into public.puzzles
  (puzzle_key, title, accepted_answers, outcome_type, outcome_payload, movement, active, max_attempts)
values

-- ===========================================================================
-- MOVEMENT I — The Notice (entry surface)
-- ===========================================================================

